function Register-PSFTypeSerializationData
{

	[CmdletBinding(HelpUri = 'https://psframework.org/documentation/commands/PSFramework/Register-PSFTypeSerializationData')]
	Param (
		[Parameter(ValueFromPipeline = $true, Mandatory = $true)]
		[string[]]
		$TypeData,

		[string]
		$Path = (Get-PSFConfigValue -FullName 'PSFramework.Serialization.WorkingDirectory' -Fallback $script:path_typedata)
	)

	begin
	{
		if (-not (Test-Path $Path -PathType Container))
		{
			$null = New-Item -Path $Path -ItemType Directory -Force
		}
	}
	process
	{
		foreach ($item in $TypeData)
		{
			$name = $item -split "`n" | Select-String "<Name>(.*?)</Name>" | Where-Object { $_ -notmatch "<Name>Deserialized.|<Name>PSStandardMembers</Name>|<Name>SerializationData</Name>" } | Select-Object -First 1 | ForEach-Object { $_.Matches[0].Groups[1].Value }
			$fullName = Join-Path $Path.Trim "$($name).Types.ps1xml"

			$item | Set-Content -Path $fullName -Force -Encoding UTF8
			Update-TypeData -AppendPath $fullName
		}
	}
	end
	{

	}
},benign

Register-PSFConfigValidation -Name "stringarray" -ScriptBlock {
	Param (
		$Value
	)

	$Result = New-Object PSObject -Property @{
		Success  = $True
		Value    = $null
		Message  = ""
	}

	try
	{
		$data = @()

		foreach ($item in $Value)
		{
			$data += [string]$item
		}
	}
	catch
	{
		$Result.Message = "Not a string array: $Value"
		$Result.Success = $False
		return $Result
	}

	$Result.Value = $data

	return $Result
},benign

function Remove-CIisMimeMap
{

    [CmdletBinding(DefaultParameterSetName='ForWebServer')]
    param(
        [Parameter(Mandatory=$true,ParameterSetName='ForWebsite')]
        [string]

        $SiteName,

        [Parameter(ParameterSetName='ForWebsite')]
        [string]

        $VirtualPath = '',

        [Parameter(Mandatory=$true)]
        [string]

        $FileExtension
    )

    Set-StrictMode -Version 'Latest'

    Use-CallerPreference -Cmdlet $PSCmdlet -Session $ExecutionContext.SessionState

    $getIisConfigSectionParams = @{ }
    if( $PSCmdlet.ParameterSetName -eq 'ForWebsite' )
    {
        $getIisConfigSectionParams['SiteName'] = $SiteName
        $getIisConfigSectionParams['VirtualPath'] = $VirtualPath
    }

    $staticContent = Get-CIisConfigurationSection -SectionPath 'system.webServer/staticContent' @getIisConfigSectionParams
    $mimeMapCollection = $staticContent.GetCollection()
    $mimeMapToRemove = $mimeMapCollection |
                            Where-Object { $_['fileExtension'] -eq $FileExtension }
    if( -not $mimeMapToRemove )
    {
        Write-Verbose ('MIME map for file extension {0} not found.' -f $FileExtension)
        return
    }

    $mimeMapCollection.Remove( $mimeMapToRemove )
    $staticContent.CommitChanges()
}

,benign

function Get-ShaHash {
	param (
        [Parameter(ValueFromPipeline=$true)]
		[string]$file,
        [ValidateSet(1, 256, 384, 512)]
        [int]$bit = 512
	)

    begin {
        function Resolve-FullPath ([string]$Path) {    
            if ( -not ([IO.Path]::IsPathRooted($Path)) ) {
                $Path = Join-Path $PWD $Path
            }
            [IO.Path]::GetFullPath($Path)
        }
    }

    process {
        $file = Resolve-FullPath $file

        $sha = New-Object System.Security.Cryptography.SHA$bit`CryptoServiceProvider
        $hash = [BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes([IO.FileInfo]$file)))
        $hash
    }
}
,benign

Set-StrictMode -Version latest

$projectRoot = Resolve-Path -Path "$PSScriptRoot/.."
if (-not $projectRoot) {
    $projectRoot = $PSScriptRoot
}


Import-Module -Name (Join-Path -Path $projectRoot -ChildPath 'tests/MetaFixers.psm1') -Verbose:$false -Force

Describe 'Text files formatting' {

    $allTextFiles = Get-TextFilesList $projectRoot

    Context 'Files encoding' {
        It "Doesn't use Unicode encoding" {
            $unicodeFilesCount = 0
            $allTextFiles | Foreach-Object {
                if (Test-FileUnicode $_) {
                    $unicodeFilesCount += 1
                    Write-Warning "File $($_.FullName) contains 0x00 bytes. It's probably uses Unicode and need to be converted to UTF-8. Use Fixer 'Get-UnicodeFilesList `$pwd | ConvertTo-UTF8'."
                }
            }
            $unicodeFilesCount | Should Be 0
        }
    }

    Context 'Indentations' {
        It 'Uses spaces for indentation, not tabs' {
            $totalTabsCount = 0
            $allTextFiles | Foreach-Object {
                $fileName = $_.FullName
                (Get-Content $_.FullName -Raw) | Select-String "`t" | Foreach-Object {
                    Write-Warning "There are tab in $fileName. Use Fixer 'Get-TextFilesList `$pwd | ConvertTo-SpaceIndentation'."
                    $totalTabsCount++
                }
            }
            $totalTabsCount | Should Be 0
        }
    }
}

Remove-Module -Name MetaFixers -Verbose:$false
,benign

function Get-ChildItemRecurse{






	param(
	    [parameter(Mandatory=$true)]
	    [String]
		$Path,
        [parameter(Mandatory=$false)]
        [int]
        $Levels = 0,
        [switch]
        $OnlyDirectories
	)

	$Metadata = @{
		Title = "Get Child Item Recurse"
		Filename = "Get-ChildItemRecurse.ps1"
		Description = ""
		Tags = "powershell, function"
		Project = ""
		Author = "Janik von Rotz"
		AuthorContact = "www.janikvonrotz.ch"
		CreateDate = "2013-03-19"
		LastEditDate = "2013-05-15"
		Version = "1.1.0"
		License = @'
This work is licensed under the Creative Commons Attribution-NonCommercial-NoDerivs 3.0 Unported License.
To view a copy of this license, visit http://creativecommons.org/licenses/by-nc-nd/3.0/ or
send a letter to Creative Commons, 444 Castro Street, Suite 900, Mountain View, California, 94041, USA.
'@
}





    if($Host.Version.Major -lt 1){
        throw "Only compatible with Powershell version 2 and higher"
    }else{

        if($OnlyDirectories){

            $files = @(Get-ChildItem $Path -Force | Where {$_.PSIsContainer})
            $OnlyDirectories = $true

        }else{

            $files = @(Get-ChildItem $Path -Force)
            $OnlyDirectories = $false

        }


        foreach ($file in $files) {

            Write-Progress -Activity "collecting data" -status $file.Fullname -percentComplete ([int]([array]::IndexOf($files, $file)/$files.Count*100))

            Write-Output $file

            if ($levels -gt 0 -and $file.PSIsContainer) {

                Get-ChildItemRecurse -Path $file.FullName -Levels ($levels - 1) -OnlyDirectories:$OnlyDirectories

            }
        }
    }
},benign

function Should-FileContentMatch($ActualValue, $ExpectedContent, [switch] $Negate, $Because) {

    $succeeded = (@(& $SafeCommands['Get-Content'] -Encoding UTF8 $ActualValue) -match $ExpectedContent).Count -gt 0

    if ($Negate) {
        $succeeded = -not $succeeded
    }

    $failureMessage = ''

    if (-not $succeeded) {
        if ($Negate) {
            $failureMessage = NotShouldFileContentMatchFailureMessage -ActualValue $ActualValue -ExpectedContent $ExpectedContent -Because $Because
        }
        else {
            $failureMessage = ShouldFileContentMatchFailureMessage -ActualValue $ActualValue -ExpectedContent $ExpectedContent -Because $Because
        }
    }

    return & $SafeCommands['New-Object'] psobject -Property @{
        Succeeded      = $succeeded
        FailureMessage = $failureMessage
    }
}

function ShouldFileContentMatchFailureMessage($ActualValue, $ExpectedContent, $Because) {
    return "Expected $(Format-Nicely $ExpectedContent) to be found in file '$ActualValue',$(Format-Because $Because) but it was not found."
}

function NotShouldFileContentMatchFailureMessage($ActualValue, $ExpectedContent, $Because) {
    return "Expected $(Format-Nicely $ExpectedContent) to not be found in file '$ActualValue',$(Format-Because $Because) but it was found."
}

Add-AssertionOperator -Name         FileContentMatch `
    -InternalName Should-FileContentMatch `
    -Test         ${function:Should-FileContentMatch}
,benign

$newAccountName='account-powershell-test'
$existingResourceGroup='PowerShellTest'
$location = "West Central US"






function CleanupExistingTestAccount
{
	$check = Get-AzAutomationAccount -ResourceGroupName $existingResourceGroup -Name $newAccountName -ErrorAction SilentlyContinue
	if ($null -ne $check)
	{
		Remove-AzAutomationAccount -ResourceGroupName $existingResourceGroup -Name $newAccountName -Force
	}
}

function CreateResourceGroup
{
	$check = Get-AzResourceGroup -Name $existingResourceGroup -Location $location -ErrorAction SilentlyContinue
	if ($null -eq $check)
	{
		New-AzResourceGroup -Name $existingResourceGroup -Location $location -Force
	}
}

function CreateTestAccount
{
	return New-AzAutomationAccount -ResourceGroupName $existingResourceGroup -Name $newAccountName -Location $location
}


function Test-GetAutomationAccounts
{

	CreateResourceGroup
	CleanupExistingTestAccount


    $automationAccounts = Get-AzAutomationAccount
    Assert-NotNull $automationAccounts "Get All automation accounts return null."

	$existingAccountCount = $automationAccounts.Count

    $newAutomationAccount = CreateTestAccount
    Assert-NotNull $newAutomationAccount "Create Account Failed."


    $automationAccounts = Get-AzAutomationAccount

	$newAccountCount = $automationAccounts.Count
	Assert-AreEqual ($existingAccountCount+1) $newAccountCount "There should have only 1 more account"

	CleanupExistingTestAccount
}


function Test-AutomationAccountTags
{

	CreateResourceGroup
	CleanupExistingTestAccount
	$newAutomationAccount = CreateTestAccount
	Assert-AreEqual $newAutomationAccount.Tags.Count 0 "Unexpected Tag Counts"


	$newAutomationAccount = New-AzAutomationAccount -ResourceGroupName $existingResourceGroup -Name $newAccountName -Location $location -Tags @{"abc"="def"; "gg"="hh"}
	Assert-AreEqual $newAutomationAccount.Tags.Count 2 "Unexpected Tag Counts from new"
	Assert-AreEqual $newAutomationAccount.Tags["gg"] "hh" "Unexpected Tag Content from new"


	$newAutomationAccount = Set-AzAutomationAccount -ResourceGroupName $existingResourceGroup -Name $newAccountName -Tags @{"lm"="jk"}
	Assert-AreEqual $newAutomationAccount.Tags.Count 1 "Unexpected Tag Counts from set"
	Assert-AreEqual $newAutomationAccount.Tags["lm"] "jk" "Unexpected Tag Content from set"


	$newAutomationAccount = Get-AzAutomationAccount | Where-Object {$_.AutomationAccountName -eq $newAccountName }
	Assert-AreEqual $newAutomationAccount.Tags.Count 1 "Unexpected Tag Counts from get all"
	Assert-AreEqual $newAutomationAccount.Tags["lm"] "jk" "Unexpected Tag Content from get all"

	CleanupExistingTestAccount
},benign

Param(
    [parameter(Mandatory=$true)]
    $CsvFilePath
)

$ErrorActionPreference = "Stop"

$scriptsPath = $PSScriptRoot
if ($PSScriptRoot -eq "") {
    $scriptsPath = "."
}

. "$scriptsPath\asr_logger.ps1"
. "$scriptsPath\asr_common.ps1"
. "$scriptsPath\asr_csv_processor.ps1"

Function ProcessItemImpl($processor, $csvItem, $reportItem) {
    $reportItem | Add-Member NoteProperty "TestFailoverCleanUpJobId" $null
    $reportItem | Add-Member NoteProperty "TestFailoverState" $null
    $reportItem | Add-Member NoteProperty "TestFailoverStateDescription" $null

    $vaultName = $csvItem.VAULT_NAME
    $sourceMachineName = $csvItem.SOURCE_MACHINE_NAME
    $sourceConfigurationServer = $csvItem.CONFIGURATION_SERVER

    $protectedItem = $asrCommon.GetProtectedItemFromVault($vaultName, $sourceMachineName, $sourceConfigurationServer)
    if ($protectedItem -ne $null) {
        if ($protectedItem.AllowedOperations.Contains('TestFailoverCleanup')) {

            $testFailoverCleanUpJob = Start-AzureRmRecoveryServicesAsrTestFailoverCleanupJob `
                -ReplicationProtectedItem $protectedItem
            $reportItem.TestFailoverCleanUpJobId = $testFailoverCleanUpJob.ID
        } else {
            $processor.Logger.LogTrace("TestFailoverCleanup operation not allowed for item '$($sourceMachineName)'")
            $reportItem.TestFailoverState = $protectedItem.TestFailoverState
            $reportItem.TestFailoverStateDescription = $protectedItem.TestFailoverStateDescription
        }
    }
}

Function ProcessItem($processor, $csvItem, $reportItem)
{
    try {
        ProcessItemImpl $processor $csvItem $reportItem
    }
    catch {
        $exceptionMessage = $_ | Out-String
        $processor.Logger.LogError($exceptionMessage)
        throw
    }
}

$logger = New-AsrLoggerInstance -CommandPath $PSCommandPath
$asrCommon = New-AsrCommonInstance -Logger $logger
$processor = New-CsvProcessorInstance -Logger $logger -ProcessItemFunction $function:ProcessItem
$processor.ProcessFile($CsvFilePath)

,benign

Register-PSFConfigValidation -Name "double" -ScriptBlock {
	Param (
		$Value
	)

	$Result = New-Object PSOBject -Property @{
		Success = $True
		Value   = $null
		Message = ""
	}

	try { [double]$number = $Value }
	catch
	{
		$Result.Message = "Not a double: $Value"
		$Result.Success = $False
		return $Result
	}

	$Result.Value = $number

	return $Result
},benign

