    (($_.GetValue('Publisher') -eq 'Oracle') -or
    ($_.GetValue('Publisher') -eq 'Sun Microsystems, Inc.')) -and
    ($VersionsToKeep -notcontains $_.GetValue('DisplayName'))} 

foreach ($Path in $RegUninstallPaths) {
