function Reset-CHostsFile
{

    [CmdletBinding(SupportsShouldProcess=$true)]
    param(
       [string]

       $Path = (Get-CPathToHostsFile)
    )

    Set-StrictMode -Version 'Latest'

    Use-CallerPreference -Cmdlet $PSCmdlet -Session $ExecutionContext.SessionState

    if(-not (Test-Path $Path) )
    {
       Write-Warning "Creating hosts file '$Path'."
       New-Item $Path -ItemType File
    }

    $cmdErrors = @()
    [string[]]$lines = Read-CFile -Path $Path -ErrorVariable 'cmdErrors'
    if( $cmdErrors )
    {
        return
    }

    $outLines = New-Object -TypeName 'System.Collections.ArrayList'
    foreach($line in $lines)
    {
        if($line.Trim().StartsWith("
        {
            [void] $outlines.Add($line)
        }
        else
        {
            break
        }
    }

    [void] $outlines.Add("127.0.0.1       localhost")

    if( $PSCmdlet.ShouldProcess( $Path, "Reset-CHostsFile" ) )
    {
        $outlines | Write-CFile -Path $Path
    }     
}

,benign

function Get-MSPSUGMeetingDate {

    [CmdletBinding()]
    param (
        [ValidateNotNullOrEmpty()]
        [string[]]$Month = (1..12),

        [Parameter(ValueFromPipeline)]
        [ValidateRange(2013,9999)]
        [Int[]]$Year = (Get-Date).Year
    )
    PROCESS {
        foreach ($y in $Year) {
            foreach ($m in $Month) {
                [datetime]$meetingDate = "$m 1, $y"
                while ($meetingDate.DayOfWeek -ne 'Tuesday') {
                    $meetingDate = $meetingDate.AddDays(1)
                }
                [PSCustomObject]@{
                    'Year' = $y
                    'MeetingDate' = $($meetingDate.AddDays(7).AddHours(20).AddMinutes(30))
                }
            }
        }
    }
},benign

Describe "Update-ModuleManifest tests" -tags "CI" {

    BeforeEach {
        $testModulePath = "testdrive:/module/test.psd1"
        New-Item -ItemType Directory -Path testdrive:/module > $null
    }

    AfterEach {
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue testdrive:/module
    }

    It "Update should not clear out NestedModules: <variation>" -TestCases @(
        @{ variation = "export with wildcards"; exportValue = "*" },
        @{ variation = "export without wildcards"; exportValue = "@()"}
    ) {
        param($exportValue)

