function Set-MrInternetConnectionSharing {



    [CmdletBinding()]
    param (
        [Parameter(Mandatory,
                   ValueFromPipeline,
                   ValueFromPipelineByPropertyName)]
        [ValidateScript({
            If ((Get-NetAdapter -Name $_ -ErrorAction SilentlyContinue -OutVariable INetNIC) -and (($INetNIC).Status -ne 'Disabled' -or ($INetNIC).Status -ne 'Not Present')) {
                $True
            }
            else {
                Throw "$_ is either not a valid network adapter of it's currently disabled."
            }
        })]
        [Alias('Name')]
        [string]$InternetInterfaceName,

        [ValidateScript({
            If ((Get-NetAdapter -Name $_ -ErrorAction SilentlyContinue -OutVariable LocalNIC) -and (($LocalNIC).Status -ne 'Disabled' -or ($INetNIC).Status -ne 'Not Present')) {
                $True
            }
            else {
                Throw "$_ is either not a valid network adapter of it's currently disabled."
            }
        })]
        [string]$LocalInterfaceName,

        [Parameter(Mandatory)]
        [bool]$Enabled
    )

    BEGIN {
        if ((Get-NetAdapter | Get-MrInternetConnectionSharing).SharingEnabled -contains $true -and $Enabled) {
            Write-Warning -Message 'Unable to continue due to Internet connection sharing already being enabled for one or more network adapters.'
            Break
        }

        regsvr32.exe /s hnetcfg.dll
        $netShare = New-Object -ComObject HNetCfg.HNetShare
    }

    PROCESS {

        $publicConnection = $netShare.EnumEveryConnection |
        Where-Object {
            $netShare.NetConnectionProps.Invoke($_).Name -eq $InternetInterfaceName
        }

        $publicConfig = $netShare.INetSharingConfigurationForINetConnection.Invoke($publicConnection)

        if ($PSBoundParameters.LocalInterfaceName) {
            $privateConnection = $netShare.EnumEveryConnection |
            Where-Object {
                $netShare.NetConnectionProps.Invoke($_).Name -eq $LocalInterfaceName
            }

            $privateConfig = $netShare.INetSharingConfigurationForINetConnection.Invoke($privateConnection)
        } 

        if ($Enabled) {
            $publicConfig.EnableSharing(0)
            if ($PSBoundParameters.LocalInterfaceName) {
                $privateConfig.EnableSharing(1)
            }
        }
        else {
            $publicConfig.DisableSharing()
            if ($PSBoundParameters.LocalInterfaceName) {
                $privateConfig.DisableSharing()
            }
        }

    }

},benign

function diskfree {
    Param (
        [parameter(ValueFromPipeline=$true,ValueFromPipelineByPropertyName=$true)]
        [string[]]$ComputerName = $env:computername
    )

    foreach ($Computer in $ComputerName) {
        Write-Host "Working on $Computer"
        if (Test-Connection -ComputerName $Computer -Count 1 -ea 0) {
            $VolumesInfo = Get-WmiObject Win32_Volume -ComputerName $Computer -Filter "drivetype = '2' OR drivetype = '3'"
            foreach ($Volume in $VolumesInfo) {
                $Capacity = [System.Math]::Round(($Volume.Capacity/1GB),2)
                $FreeSpace = [System.Math]::Round(($Volume.FreeSpace/1GB),2)
                $UsedSpace = [System.Math]::Round(($Capacity - $FreeSpace),2)
                $PctFreeSpace = [System.Math]::Round(($Volume.FreeSpace/$Volume.Capacity)*100,2)
                [pscustomobject]@{
                    ComputerName = $computer
                    DriveName = $Volume.Caption
                    DriveType = $Volume.DriveType
                    CapacityGB = $Capacity
                    FreeSpaceGB = $FreeSpace
                    UsedSpaceGB = $UsedSpace
                    PercentFreeGB = $PctFreeSpace
                }
            }
        } else {
            Write-Host "$Computer is not reachable"
            [pscustomobject]@{
                ComputerName = $computer
                DriveName = '-'
                DriveType = '-'
                CapacityGB = '-'
                FreeSpaceGB = '-'
                UsedSpaceGB = '-'
                PercentFreeGB = '-'
            }
        }
    }
}
,benign

function Get-HostFileEntries{




    [CmdletBinding()]
	param(
		[Parameter(Mandatory=$false)]
		[String]
		$Filter
	)




    function New-ObjectHostFileEntry{
        param(
            [string]$IP,
            [string]$DNS
        )
        New-Object PSObject -Property @{
            IP = $IP
            DNS = $DNS
        }
    }





    $Entries = $(get-content "$env:windir\System32\drivers\etc\hosts") | %{

        if(!$_.StartsWith("

            $IP = ([regex]"(([2]([0-4][0-9]|[5][0-5])|[0-1]?[0-9]?[0-9])[.]){3}(([2]([0-4][0-9]|[5][0-5])|[0-1]?[0-9]?[0-9]))").match($_).value
            $DNS = ($_ -replace $IP, "") -replace  '\s+',""

            if($Filter -and (($IP -match $Filter) -or ($DNS -match $Filter))){

                New-ObjectHostFileEntry -IP $IP -DNS $DNS

            }elseif($Filter -eq ""){

                New-ObjectHostFileEntry -IP $IP -DNS $DNS
            }
        }  
    } 

    if($Entries -ne $Null){                
        $Entries      
    }else{
        Write-Error "No entries found in host file"
    }
