function ConvertMySqlRow-ToJson
{


	[CmdletBinding()]
	[OutputType('System.IO.FileInfo')]
	param
	(
		[Parameter(Mandatory, ValueFromPipeline)]
		[ValidateNotNullOrEmpty()]
		[System.Data.DataRow[]]$Row,

		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[ValidatePattern('\.json$')]
		[ValidateScript({ -not (Test-Path -Path $_ -PathType Leaf) })]
		[string]$Path
	)
	begin
	{
		$ErrorActionPreference = 'Stop'
		$null = New-Item -Path $Path -ItemType File
	}
	process
	{
		try
		{
			foreach ($r in $row)
			{
				$properties = $r.psobject.Properties.where{ $_.Value -is [string] -and $_.Name -ne 'RowError' }
				$items = [System.Collections.ArrayList]@()
				foreach ($p in $properties)
				{
					$null = $items.Add([PSCustomObject]@{$p.Name = $p.Value })
				}
				$items | ConvertTo-Json | Out-File -Append -FilePath $Path
			}
		}
		catch
		{
			Write-Error $_.Exception.Message
		}
	}
	end
	{	
		Get-Item -Path $Path
	}
},benign

function Add-SPOFieldsToList
{

	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory=$true, Position=1)]
		[string[][]]$fields,

		[Parameter(Mandatory=$true, Position=2)]
		[string]$listTitle
	)

    foreach($field in $fields)
    {
        $fieldName = $field[0]
        $fieldType = $field[1]
        $fieldValue = $field[2]

        switch ($fieldType)
        {
            "Text"
            {
                Add-SPOTextFieldtoList $listTitle $fieldName
            }
            "Note"
            {
                Add-SPONoteFieldtoList $listTitle $fieldName
            }
            "DateTime"
            {
                Add-SPODateTimeFieldtoList $listTitle $fieldName
            }
            "Currency"
            {
                Add-SPOCurrencyFieldtoList $listTitle $fieldName
            }
            "Number"
            {
                Add-SPOCurrencyFieldtoList $listTitle $fieldName
            }
            "Choice"
            {
                Add-SPOChoiceFieldtoList $listTitle $fieldName $fieldValue
            }
            "Person or Group"
            {
                Add-SPOUserFieldtoList $listTitle $fieldName
            }
            "Calculated"
            {
                Add-SPOCalculatedFieldtoList $listTitle $fieldName $fieldValue
            }
        }
    }
}
,benign

