Function Remove-HashTableEmptyValue
{

    [CmdletBinding()]
    PARAM([System.Collections.Hashtable]$HashTable)

    $HashTable.GetEnumerator().name |
        ForEach-Object -Process {
            if($HashTable[$_] -eq "" -or $HashTable[$_] -eq $null)
            {
                Write-Verbose -Message "[Remove-HashTableEmptyValue][PROCESS] - Property: $_ removing..."
                [void]$HashTable.Remove($_)
                Write-Verbose -Message "[Remove-HashTableEmptyValue][PROCESS] - Property: $_ removed"
            }
        }
},benign

function ConvertFrom-Bytes {
    param (
        [string]$bytes,
        [string]$savepath
    )

    $dir = Split-Path $savepath
    if (!(Test-Path $dir)) {
        md $dir | Out-Null
    }

    [convert]::FromBase64String($bytes) | Set-Content $savepath -Encoding Byte
}
,benign

$error.PSBase.Clear()

$aRegRoots = @('HKCU\Software','HKLM\System','HKLM\Software');
$aGpos = Get-Gpo -All;
$aUniqueSettings = @();
$aUniqueDups = @();

function findRegValues($sName,$sId,$sKeyPath,$aKeyPathHistory = $null) {
	$aPath = Get-GPRegistryValue -GUID $sId -Key $sKeyPath -ErrorAction 'silentlycontinue'
	$aKeyPathHistory = @();
	foreach ($oKeyPath in $aPath) {
		if ($oKeyPath) {
			if (Test-Member $oKeyPath Value) {
				if ($aKeyPathHistory -notcontains $oKeyPath.FullKeyPath) {
					$o = New-Object System.Object;
					$o | Add-Member -type NoteProperty -Name 'GUID' -Value $sId;
					$o | Add-Member -type NoteProperty -Name 'Name' -Value $sName;
					$o | Add-Member -type NoteProperty -Name 'Key' -Value $sKeyPath;
					$o | Add-Member -type NoteProperty -Name 'Value' -Value $oKeyPath.Value;
					if ($aUniqueSettings -notcontains "$sKeyPath|$($oKeyPath.Value)") {
						$aUniqueSettings += "$sKeyPath|$($oKeyPath.Value)";
					} elseif ($aUniqueDups -notcontains "$sKeyPath|$($oKeyPath.Value)") {
						"$sName|$sKeyPath|$($oKeyPath.Value)";
						$aUniqueDups += "$sKeyPath|$($oKeyPath.Value)";
					}
				}
			} elseif (Test-Member $oKeyPath FullKeyPath) {
				$aKeyPathHistory += $oKeyPath.FullKeyPath;
				findRegValues $sName $sId $oKeyPath.FullKeyPath $aKeyPathHistory
			}
		}
	}
}

$aRegValues = @();

foreach ($oGpo in $aGpos) {
	$sGuid = $oGpo.Id;
	$sName = $oGpo.DisplayName;
	foreach ($sRegRoot in $aRegRoots) {
		findRegValues $sName $sGuid $sRegRoot
	}
},benign

function Test-Capabilities
{
	$location = "eastus"
	$all = Get-AzSqlCapability $location
	Validate-Capabilities $all

	$default = Get-AzSqlCapability $location -Defaults
	Validate-Capabilities $default

	$version = Get-AzSqlCapability $location -ServerVersionName "12.0"
	Validate-Capabilities $default

	$edition = Get-AzSqlCapability $location -EditionName "Premium"
	Validate-Capabilities $default

	$so = Get-AzSqlCapability $location -ServiceObjectiveName "S3"
	Validate-Capabilities $default

}


function Validate-Capabilities ($capabilities)
{
	Assert-NotNull $capabilities
	Assert-AreEqual $capabilities.Status "Default"
	Assert-True {$capabilities.SupportedServerVersions.Count -gt 0}

	foreach($version in $capabilities.SupportedServerVersions) {
		Assert-NotNull $version
		Assert-NotNull $version.ServerVersionName
		Assert-NotNull $version.Status
		Assert-True {$version.SupportedEditions.Count -gt 0}

		foreach($edition in $version.SupportedEditions) {
			Assert-NotNull $edition
			Assert-NotNull $edition.EditionName
			Assert-NotNull $edition.Status
			Assert-True {$edition.SupportedServiceObjectives.Count -gt 0}

			foreach($so in $edition.SupportedServiceObjectives) {
				Assert-NotNull $so
				Assert-NotNull $so.ServiceObjectiveName
				Assert-NotNull $so.Status
				Assert-NotNull $so.Id
				Assert-AreNotEqual $so.Id [System.Guid]::Empty


				foreach($size in $so.SupportedMaxSizes) {
					Assert-NotNull $size
					Assert-NotNull $size.MinValue.Limit
					Assert-True { $size.MinValue.Limit -gt 0 }
					Assert-NotNull $size.MinValue.Unit

					Assert-NotNull $size.MaxValue.Limit
					Assert-True { $size.MaxValue.Limit -gt 0 }
					Assert-NotNull $size.MaxValue.Unit

					Assert-NotNull $size.ScaleSize.Limit
					Assert-NotNull $size.ScaleSize.Unit

					Assert-NotNull $size.Status
				}
			}
		}
	}
}
,benign

function Test-NetworkUsage
{

    $rgname = Get-ResourceGroupName
    $vnetName = Get-ResourceName
    $subnetName = Get-ResourceName
    $rglocation = Get-ProviderLocation ResourceManagement
    $resourceTypeParent = "Microsoft.Network/Usages"
    $location = Get-ProviderLocation $resourceTypeParent "West US" -UseCanonical $true

    try 
    {
        $usage = Get-AzNetworkUsage -Location $location;
        $vnetCount = ($usage | Where-Object { $_.name.Value -eq "VirtualNetworks" }).currentValue;
        Assert-AreNotEqual 0 $usage.Length "Usage should return non-empty array";


        $resourceGroup = New-AzResourceGroup -Name $rgname -Location $rglocation


        New-AzVirtualNetwork -Name $vnetName -ResourceGroupName $rgname -Location $location -AddressPrefix 10.0.0.0/16 -DnsServer 8.8.8.8;
        $usage = Get-AzNetworkUsage -Location $location;
        $vnetCount2 = ($usage | Where-Object { $_.name.Value -eq "VirtualNetworks" }).currentValue;

        Assert-AreEqual ($vnetCount + 1) $vnetCount2 "Virtual Networks usage current value should be increased after Virtual Network was created";
    }
    finally
    {

        Clean-ResourceGroup $rgname
    }
}
,benign

