function Test-Port {
    param (
        $ip = '127.0.0.1',
        $port = '515'
    )

    begin {
        $tcp = New-Object Net.Sockets.TcpClient
    }

    process {
        try {
            $tcp.Connect($ip, $port)
        } catch {}

        if ($tcp.Connected) {
            $tcp.Close()
            $open = $true
        } else {
            $open = $false
        }

        [pscustomobject]@{
            IP = $ip
            Port = $port
            Open = $open
        }
    }
}
,benign

function Get-LogFast
{

	[CmdletBinding()]
	PARAM (
		$Path = "c:\Biglog.log",

		$Match
	)
	BEGIN
	{


		$StreamReader = New-object -TypeName System.IO.StreamReader -ArgumentList (Resolve-Path -Path $Path -ErrorAction Stop).Path
	}
	PROCESS
	{

		while ($StreamReader.Peek() -gt -1)
		{


			$Line = $StreamReader.ReadLine()


			if ($Line.length -eq 0 -or $Line -match "^
			{
				continue
			}

			IF ($PSBoundParameters['Match'])
			{
				If ($Line -match $Match)
				{
					Write-Verbose -Message "[PROCESS] Match found"




					Write-Output $Line
				}
			}
			ELSE { Write-Output $Line }
		}
	} 
},benign

