[CmdletBinding(SupportsShouldProcess=$true)]
param(
    [parameter(Mandatory=$true, HelpMessage="Site server where the SMS Provider is installed")]
    [ValidateNotNullOrEmpty()]
    [ValidateScript({Test-Connection -ComputerName $_ -Count 1 -Quiet})]
    [string]$SiteServer,
    [parameter(Mandatory=$true, HelpMessage="Specify a Device names that has a user machine relationship that will be removed")]
    [ValidateNotNullOrEmpty()]
    [string[]]$DeviceName
)
Begin {

    try {
        Write-Verbose "Determining SiteCode for Site Server: '$($SiteServer)'"
        $SiteCodeObjects = Get-WmiObject -Namespace "root\SMS" -Class SMS_ProviderLocation -ComputerName $SiteServer -ErrorAction Stop
        foreach ($SiteCodeObject in $SiteCodeObjects) {
            if ($SiteCodeObject.ProviderForLocalSite -eq $true) {
                $SiteCode = $SiteCodeObject.SiteCode
                Write-Debug "SiteCode: $($SiteCode)"
            }
        }
    }
    catch [System.UnauthorizedAccessException] {
        Write-Warning -Message "Access denied" ; break
    }
    catch [Exception] {
        Write-Warning -Message "Unable to determine SiteCode" ; break
    }
}
Process {
    try {
        foreach ($Device in $DeviceName) {
            $UserMachineRelations = Get-WmiObject -Namespace "root\SMS\site_$($SiteCode)" -Class SMS_UserMachineRelationship -ComputerName $SiteServer -Filter "ResourceName like '$($Device)'"
            if ($UserMachineRelations -ne $null) {
                if ($PSCmdlet.ShouldProcess($UserMachineRelations.__PATH, "Remove")) {
                    Remove-WmiObject -InputObject $UserMachineRelations
                }
            }
        }
    }
    catch [System.UnauthorizedAccessException] {
        Write-Warning -Message "Access denied"
    }
    catch [Exception] {
        Write-Error -Message "An error occured while trying to remove a WMI instance"
    }
},benign

function Out-Menu {
    param (
        [Parameter(
            Mandatory=$true,
            ValueFromPipeline=$True,
            ValueFromPipelinebyPropertyName=$True)]
        [object[]]$Object,
        [string]$Header,
        [string]$Footer,
        [switch]$AllowCancel,
        [switch]$AllowMultiple
    )

    if ($input) {
        $Object = @($input)
    }

    if (!$Object) {
        throw 'Must provide an object.'
    }

    Write-Host ''

    do {
        $prompt = New-Object System.Text.StringBuilder
        switch ($true) {
            {[bool]$Header -and $Header -notmatch '^(?:\s+)?$'} { $null = $prompt.Append($Header); break }
            $true { $null = $prompt.Append('Choose an option') }
            $AllowCancel { $null = $prompt.Append(', or enter "c" to cancel.') }
            $AllowMultiple {$null = $prompt.Append("`nTo select multiple, enter numbers separated by a comma EX: 1, 2") }
        }
        Write-Host $prompt.ToString()

        $nums = $Object.Count.ToString().Length
        for ($i = 0; $i -lt $Object.Count; $i++) {
            Write-Host "$("{0:D$nums}" -f ($i+1)). $($Object[$i])"
        }

        if ($Footer) {
            Write-Host $Footer
        }

        Write-Host ''

        if ($AllowMultiple) {
            $answers = @(Read-Host).Split(',').Trim()

            if ($AllowCancel -and $answers -match 'c') {
                return
            }

            $ok = $true
            foreach ($ans in $answers) {
                if ($ans -in 1..$Object.Count) {
                    $Object[$ans-1]
                } else {
                    Write-Host 'Not an option!' -ForegroundColor Red
                    Write-Host ''
                    $ok = $false
                }
            }
        } else {
            $answer = Read-Host

            if ($AllowCancel -and $answer -eq 'c') {
                return
            }

            $ok = $true
            if ($answer -in 1..$Object.Count) {
                $Object[$answer-1]
            } else {
                Write-Host 'Not an option!' -ForegroundColor Red
                Write-Host ''
                $ok = $false
            }
        }
    } while (!$ok)
}

Set-Alias -Name Menu -Value Out-Menu
,benign

function Test-Credential { 

    [cmdletbinding(DefaultParameterSetName = 'Domain')]
    param(
        [parameter(ValueFromPipeline=$true)]
        [System.Management.Automation.PSCredential]$Credential = $( Get-Credential -Message "Please provide credentials to test" ),

        [validateset('Domain','Machine', 'ApplicationDirectory')]
        [string]$Context = 'Domain',

        [parameter(ParameterSetName = 'Machine')]
        [string]$ComputerName,

        [parameter(ParameterSetName = 'Domain')]
        [string]$Domain = $null
    )
    Begin
    {
        Write-Verbose "ParameterSetName: $($PSCmdlet.ParameterSetName)`nPSBoundParameters: $($PSBoundParameters | Out-String)"
        Try
        {
            Add-Type -AssemblyName System.DirectoryServices.AccountManagement
        }
        Catch
        {
            Throw "Could not load assembly: $_"
        }


        if ($Context -eq 'ApplicationDirectory' )
        {

            $DS = New-Object System.DirectoryServices.AccountManagement.PrincipalContext([System.DirectoryServices.AccountManagement.ContextType]::$Context)
        }
        elseif ($PSCmdlet.ParameterSetName -eq 'Domain')
        {
            $Context = $PSCmdlet.ParameterSetName
            $DS = New-Object System.DirectoryServices.AccountManagement.PrincipalContext([System.DirectoryServices.AccountManagement.ContextType]::$Context, $Domain)
        }
        elseif ($PSCmdlet.ParameterSetName -eq 'Machine')
        {
            $Context = $PSCmdlet.ParameterSetName
            $DS = New-Object System.DirectoryServices.AccountManagement.PrincipalContext([System.DirectoryServices.AccountManagement.ContextType]::$Context, $ComputerName)
        }

    }
    Process
    {

        $DS.ValidateCredentials($Credential.UserName, $Credential.GetNetworkCredential().password)
    }
    End
    {
        $DS.Dispose()
    }
},benign

function In {

    [CmdletBinding()]
    param(
        $path,
        [ScriptBlock] $execute
    )
    Assert-DescribeInProgress -CommandName In

    $old_pwd = $pwd
    & $SafeCommands['Push-Location'] $path
    $pwd = $path
    try {
        Write-ScriptBlockInvocationHint -Hint "In" -ScriptBlock $execute
        & $execute
    }
    finally {
        & $SafeCommands['Pop-Location']
        $pwd = $old_pwd
    }
}
,benign

function Get-PassPol
{
	$domain = [ADSI]"WinNT://$env:userdomain"
	$Name = @{Name='DomainName';Expression={$_.Name}}
	$MinPassLen = @{Name='Minimum Password Length (Chars)';Expression={$_.MinPasswordLength}}
	$MinPassAge = @{Name='Minimum Password Age (Days)';Expression={$_.MinPasswordAge.value/86400}}
	$MaxPassAge = @{Name='Maximum Password Age (Days)';Expression={$_.MaxPasswordAge.value/86400}}
	$PassHistory = @{Name='Enforce Password History (Passwords remembered)';Expression={$_.PasswordHistoryLength}}
	$AcctLockoutThreshold = @{Name='Account Lockout Threshold (Invalid logon attempts)';Expression={$_.MaxBadPasswordsAllowed}}
	$AcctLockoutDuration =  @{Name='Account Lockout Duration (Minutes)';Expression={if ($_.AutoUnlockInterval.value -eq -1) {'Account is locked out until administrator unlocks it.'} else {$_.AutoUnlockInterval.value/60}}}
	$ResetAcctLockoutCounter = @{Name='Reset Account Lockout Counter After (Minutes)';Expression={$_.LockoutObservationInterval.value/60}}
	$domain | Select-Object $Name,$MinPassLen,$MinPassAge,$MaxPassAge,$PassHistory,$AcctLockoutThreshold,$AcctLockoutDuration,$ResetAcctLockoutCounter
}
$PassPol = Get-PassPol
Write-Output 'Domain Password Policy: '
Write-Output $PassPol
,benign

function Get-WLANProfile
{
	[CmdletBinding()]
	param(
		[Parameter(
			Position=0,
			HelpMessage='Indicates that the password appears in plain text')]
		[Switch]$ShowPassword,

		[Parameter(
			Position=1,
			HelpMessage='Filter WLAN-Profiles by Name or SSID')]
		[String]$Search,

		[Parameter(
			Position=2,
			HelpMessage='Exact match, when filter WLAN-Profiles by Name or SSID')]
		[Switch]$ExactMatch
	)

	Begin{

	}

	Process{

		$Netsh_WLANProfiles = (netsh WLAN show profiles)


		$IsProfile = 0
		$WLAN_Names = @()


		foreach($Line in $Netsh_WLANProfiles)
		{
			if((($IsProfile -eq 2)) -and (-not([String]::IsNullOrEmpty($Line))))
			{
				$WLAN_Names += $Line.Split(':')[1].Trim()
			}

			if($Line.StartsWith("---"))
			{
				$IsProfile += 1
			}
		}


		foreach($WLAN_Name in $WLAN_Names)
		{
			$Netsh_WLANProfile = (netsh WLAN show profiles name="$WLAN_Name" key=clear)


			$InProfile = 0
			$IsConnectivity = 0
			$IsSecurity = 0

			foreach($Line in $Netsh_WLANProfile)
			{
				if((($InProfile -eq 2)) -and (-not([String]::IsNullOrEmpty($Line))))
				{			

					if($IsConnectivity -eq 1) 
					{ 
						$WLAN_SSID = $Line.Split(':')[1].Trim()
						$WLAN_SSID = $WLAN_SSID.Substring(1,$WLAN_SSID.Length -2)
					}

					$IsConnectivity += 1
				}

				if((($InProfile -eq 3)) -and (-not([String]::IsNullOrEmpty($Line))))
				{			
					if($IsSecurity -eq 0) 
					{
						$WLAN_Authentication = $Line.Split(':')[1].Trim()
					}
					elseif($IsSecurity -eq 3) 
					{
						$WLAN_Password_PlainText = $Line.Split(':')[1].Trim()
					}

					$IsSecurity += 1   
				}

				if($Line.StartsWith("---"))
				{
					$InProfile += 1
				}   
			}


			if($ShowPassword) 
			{
				$WLAN_Password = $WLAN_Password_PlainText
			}
			else
			{
				$WLAN_Password = ConvertTo-SecureString -String "$WLAN_Password_PlainText" -AsPlainText -Force
			}


			$WLAN_Profile = [pscustomobject] @{
				Name = $WLAN_Name
				SSID = $WLAN_SSID
				Authentication = $WLAN_Authentication
				Password = $WLAN_Password
			}


			if($PSBoundParameters.ContainsKey('Search'))
			{
				if((($WLAN_Profile.Name -like $Search) -or ($WLAN_Profile.SSID -like $Search)) -and (-not($ExactMatch) -or ($WLAN_Profile.Name -eq $Search) -or ($WLAN_Profile.SSID -eq $Search)))
				{
					$WLAN_Profile
				} 
			}
			else
			{
				$WLAN_Profile
			}        
		}
	}

	End{

	}
},benign

function Test-MrURL {
