    'Authorization'=$token.CreateAuthorizationHeader()
 }


$sourceGroupsPath = ""
if ($groupId -eq "me") {
    $sourceGroupsPath = "myorg"
} else {
    $sourceGroupsPath = "myorg/groups/$groupId"
