function Get-ComputerShares {
    param (
        [string]$comp = $env:COMPUTERNAME
    )

    if (!$comp) { throw 'No comps.' }

    $ping = New-Object System.Net.NetworkInformation.Ping
    try {
        $result = $ping.Send($comp)
    } catch {
        $result = $null
    }

    $sharename = $type = $comment = $ip = '-'
    if ($result.Status -eq 'Success') {

        $ip = $result.Address.ToString()


        $netview = iex "cmd /c net view $comp 2>&1" | ? {$_}


        if ($netview.count -lt 5) {
            [pscustomobject]@{
                Computer = $comp
                IP = $ip
                ShareName = $sharename
                Type = $type
                Comment = $comment
            }
            return
        }

        $netview = $netview | ? {$_  -match '\s{2}'} | select -Skip 1

        foreach ($line in $netview) {
            $line = $line -split '\s{2,}'

            $sharename = $line[0]
            $type = $line[1]
            $comment = $line[2]

            [pscustomobject]@{
                Computer = $comp
                IP = $ip
                ShareName = $sharename
                Type = $type
                Comment = $comment
            }
        }
    } else {
        [pscustomobject]@{
            Computer = $comp
            IP = $ip
            ShareName = $sharename
            Type = $type
            Comment = $comment
        }
    }
}
,benign

function Encode-Text {
    param (
        [string]$Text,
        [validateset('SecureString', 'SecureStringWithKey', 'Base64', 'ASCII')]
        [string]$Method = 'Base64'
    )

    process {
        if (!$Text) {
            $Text = $input
        }
    }

    end{
        switch ($method) {

            'SecureString' {
                Write-Warning "This can only be recovered by '$env:USERNAME' on computer '$env:COMPUTERNAME'"
                ConvertTo-SecureString $text -AsPlainText -Force | ConvertFrom-SecureString
            }

            'SecureStringWithKey' {
                ConvertTo-SecureString $text -AsPlainText -Force | ConvertFrom-SecureString -Key (1..16)
            }

            'Base64' {
                [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($Text))
            }


            'ASCII' {
                -join([char[]]$text | % {
                    '{0:D3}' -f ([int]$_ - 32)
                })
            }
        }
    }
}
,benign

function ConvertFrom-PSFArray
{

	[CmdletBinding()]
	param (
		[Parameter(Position = 0)]
		[string]
		$JoinBy = ', ',

		[Parameter(Position = 1)]
		[string[]]
		$PropertyName = '*',

		[Parameter(ValueFromPipeline = $true)]
		$InputObject
	)

	process
	{
		$props = [ordered]@{ }
		foreach ($property in $InputObject.PSObject.Properties)
		{

			if ($property.Value -isnot [System.Collections.ICollection])
			{
				$props[$property.Name] = $property.Value
				continue
			}



			$found = $false
			foreach ($name in $PropertyName)
			{
				if ($property.Name -like $name)
				{
					$found = $true
					break
				}
			}
			if (-not $found)
			{
				$props[$property.Name] = $property.Value
				continue
			}


			$props[$property.Name] = $property.Value -join $JoinBy
		}
		[PSCustomObject]$props
	}
},benign

