        }else{

            $Executable = "C:\Program Files\Greenshot\unins000.exe"; if(Test-Path $Executable){Start-Process -FilePath $Executable -ArgumentList "/VERYSILENT /NORESTART" -Wait}

            $_.Result = "AppUninstalled";$_
