function Get-CleanSPUrl {



	param(
		[Parameter(Mandatory=$true)]
		[String]
		$Url
	)






    [Uri]$Url = $Url


	if($Url -match "(/Forms/).*?\.(aspx$)"){



        [Uri]$ListUrl =  $Url.AbsoluteUri -replace "(/Forms/).*?\.(aspx)",""
        [Uri]$WebUrl = $Url.AbsoluteUri -replace "/([^/]*)(/Forms/).*?\.(aspx)",""

        @{ListUrl=$ListUrl;WebUrl=$Weburl}

    }elseif($Url -match "(/Lists/).*?\.(aspx$)"){



        [Uri]$ListUrl =  $Url.AbsoluteUri -replace "/([^/]*)\.(aspx)",""
        [Uri]$WebUrl = $Url.AbsoluteUri -replace "(/Lists/).*?\.(aspx)",""

        @{ListUrl=$ListUrl;WebUrl=$Weburl}

    }elseif($Url -match "/SitePages/Homepage.aspx$" -or $Url -match "/default.aspx$"){



        [uri]$WebUrl = $Url -replace "/SitePages/Homepage.aspx", "" -replace "/default.aspx",""

        @{WebUrl=$Weburl}

	}else{        
		 @{WebUrl=$Url}
	}
},benign

function Add-ItemToTfs
{	
	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[ValidateScript({ Test-Path -Path $_ })]
		[string]$ItemPath,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[ValidateScript({ Test-Path -Path $_ -PathType Leaf })]
		[string]$tfFilePath = 'C:\Program Files (x86)\Microsoft Visual Studio 12.0\Common7\IDE\TF.exe'

	)
	$ErrorActionPreference = 'Stop'
	try
	{
		Write-Verbose -Message "Adding the item [$($Itempath)] into TFS"

		$null = & $tfFilePath add $Itempath

		if (Test-Path -Path $ItemPath -PathType Container)
		{

			Get-ChildItem -Path $Itempath | ForEach-Object { $null = & $tfFilePath add $_.FullName }
		}
	}
	catch
	{
		Write-Error $_.Exception.Message
	}
}

function Submit-TfsChange
{
	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[ValidateScript({ Test-Path -Path $_ })]
		[string]$ItemPath,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[string]$Comment = 'New Checkin',

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[ValidateScript({ Test-Path -Path $_ -PathType Leaf })]
		[string]$tfFilePath = 'C:\Program Files (x86)\Microsoft Visual Studio 12.0\Common7\IDE\TF.exe'
	)
	try
	{
		Write-Verbose -Message "Checking in [$($Itempath)] to TFS"
		$null = & $tfFilePath checkin $Itempath /recursive /comment:$Comment
	}
	catch
	{
		Write-Error $_.Exception.Message
	}
},benign

function Get-IdentityPrincipalContext
{

    [CmdletBinding()]
    [OutputType([DirectoryServices.AccountManagement.PrincipalContext])]
    param(
        [Parameter(Mandatory=$true)]
        [Carbon.Identity]

        $Identity
    )

    Set-StrictMode -Version 'Latest'
    Use-CallerPreference -Cmdlet $PSCmdlet -Session $ExecutionContext.SessionState


    $machineCtx = New-Object 'DirectoryServices.AccountManagement.PrincipalContext' 'Machine',$env:COMPUTERNAME
    if( [DirectoryServices.AccountManagement.Principal]::FindByIdentity( $machineCtx, 'Sid', $Identity.Sid.Value ) )
    {
        return $machineCtx
    }

    $domainCtx = New-Object 'DirectoryServices.AccountManagement.PrincipalContext' 'Domain',$Identity.Domain
    if( [DirectoryServices.AccountManagement.PRincipal]::FindByIdentity( $domainCtx, 'Sid', $Identity.Sid.Value ) )
    {
        return $domainCtx
    }

    Write-Error -Message ('Unable to determine if principal ''{0}'' (SID: {1}; Type: {2}) is a machien or domain principal.' -f $Identity.FullName,$Identity.Sid.Value,$Identity.Type)
}
,benign

function Read-PsfConfigFile
{

	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true, ParameterSetName = 'Path')]
		[string]
		$Path,

		[Parameter(Mandatory = $true, ParameterSetName = 'Weblink')]
		[string]
		$Weblink,

		[Parameter(Mandatory = $true, ParameterSetName = 'RawJson')]
		[string]
		$RawJson
	)


	function New-ConfigItem
	{
		[Diagnostics.CodeAnalysis.SuppressMessageAttribute("PSUseShouldProcessForStateChangingFunctions", "")]
		[CmdletBinding()]
		param (
			$FullName,

			$Value,

			$Type,

			[switch]
			$KeepPersisted,

			[switch]
			$Enforced,

			[switch]
			$Policy
		)

		[pscustomobject]@{
			FullName	    = $FullName
			Value		    = $Value
			Type		    = $Type
			KeepPersisted   = $KeepPersisted
			Enforced	    = $Enforced
			Policy		    = $Policy
		}
	}

	function Get-WebContent
	{
		[CmdletBinding()]
		param (
			[string]
			$WebLink
		)

		$webClient = New-Object System.Net.WebClient
		$webClient.Encoding = [System.Text.Encoding]::UTF8
		$webClient.DownloadString($WebLink)
	}


	if ($Path)
	{
		if (-not (Test-Path $Path)) { return }
		$data = Get-Content -Path $Path -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop
	}
	if ($Weblink)
	{
		$data = Get-WebContent -WebLink $Weblink | ConvertFrom-Json -ErrorAction Stop
	}
	if ($RawJson)
	{
		$data = $RawJson | ConvertFrom-Json -ErrorAction Stop
	}

	foreach ($item in $data)
	{

		if (-not $item.Version)
		{
			New-ConfigItem -FullName $item.FullName -Value ([PSFramework.Configuration.ConfigurationHost]::ConvertFromPersistedValue($item.Value, $item.Type))
		}



		if ($item.Version -eq 1)
		{
			if ((-not $item.Style) -or ($item.Style -eq "Simple")) { New-ConfigItem -FullName $item.FullName -Value $item.Data }
			else
			{
				if (($item.Type -eq "Object") -or ($item.Type -eq 12))
				{
					New-ConfigItem -FullName $item.FullName -Value $item.Value -Type "Object" -KeepPersisted
				}
				else
				{
					New-ConfigItem -FullName $item.FullName -Value ([PSFramework.Configuration.ConfigurationHost]::ConvertFromPersistedValue($item.Value, $item.Type))
				}
			}
		}

	}
},benign

