function Get-SCSMIncidentRequestComment
{


    PARAM
    (
        [Parameter(ParameterSetName = 'General',
                   Mandatory = $true)]
        $DateTime = $((Get-Date).AddHours(-24)),

        [Parameter(ParameterSetName = 'GUID')]
        $GUID
    )
    BEGIN
    {
        $AssignedUserClassRelation = Get-SCSMRelationshipClass -Id 15e577a3-6bf9-6713-4eac-ba5a5b7c4722
    }
    PROCESS
    {

        IF ($PSBoundParameters['GUID'])
        {
            $Tickets = Get-SCSMObject -id $GUID
        }
        ELSE
        {
            if ($DateTime -is [String]) { $DateTime = Get-Date $DateTime }
            $DateTime = $DateTime.ToString(“yyy-MM-dd HH:mm:ss”)
            $Tickets = Get-SCSMObject -Class (Get-SCSMClass System.WorkItem.incident$) -Filter "CreatedDate -gt '$DateTime'" 
        }

        $Tickets |
        ForEach-Object {
            $CurrentTicket = $_
            $relatedObjects = Get-scsmrelatedobject -SMObject $CurrentTicket
            $AssignedTo = (Get-SCSMRelatedObject -SMObject $CurrentTicket -Relationship $AssignedUserClassRelation)
            Foreach ($Comment in ($relatedObjects | Where-Object { $_.classname -eq 'System.WorkItem.TroubleTicket.UserCommentLog' -or $_.classname -eq 'System.WorkItem.TroubleTicket.AnalystCommentLog' -or $_.classname -eq 'System.WorkItem.TroubleTicket.AuditCommentLog' }))
            {

                [pscustomobject][ordered] @{
                    TicketName = $CurrentTicket.Name
                    TicketClassName = $CurrentTicket.Classname
                    TicketDisplayName = $CurrentTicket.DisplayName
                    TicketID = $CurrentTicket.ID
                    TicketGUID = $CurrentTicket.get_id()
                    TicketTierQueue = $CurrentTicket.TierQueue.displayname
                    TicketAssignedTo = $AssignedTo.DisplayName
                    TicketCreatedDate = $CurrentTicket.CreatedDate
                    Comment = $Comment.Comment
                    CommentEnteredBy = $Comment.EnteredBy
                    CommentEnteredDate = $Comment.EnteredDate
                    CommentClassName = $Comment.ClassName
                }
            }
        }

    }
},benign

function Install-CIisVirtualDirectory
{

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]

        $SiteName,

        [Parameter(Mandatory=$true)]
        [Alias('Name')]
        [string]

        $VirtualPath,

        [Parameter(Mandatory=$true)]
        [Alias('Path')]
        [string]

        $PhysicalPath,

        [Switch]





        $Force
    )

    Set-StrictMode -Version 'Latest'

    Use-CallerPreference -Cmdlet $PSCmdlet -Session $ExecutionContext.SessionState

    $site = Get-CIisWebsite -Name $SiteName
    [Microsoft.Web.Administration.Application]$rootApp = $site.Applications | Where-Object { $_.Path -eq '/' }
    if( -not $rootApp )
    {
        Write-Error ('Default website application not found.')
        return
    }

    $PhysicalPath = Resolve-CFullPath -Path $PhysicalPath

    $VirtualPath = $VirtualPath.Trim('/')
    $VirtualPath = '/{0}' -f $VirtualPath

    $vdir = $rootApp.VirtualDirectories | Where-Object { $_.Path -eq $VirtualPath }
    if( $Force -and $vdir )
    {
        Write-IisVerbose $SiteName -VirtualPath $VirtualPath 'REMOVE' '' ''
        $rootApp.VirtualDirectories.Remove($vdir)
        $site.CommitChanges()
        $vdir = $null

        $site = Get-CIisWebsite -Name $SiteName
        $rootApp = $site.Applications | Where-Object { $_.Path -eq '/' }
    }

    $modified = $false

    if( -not $vdir )
    {
        [Microsoft.Web.Administration.ConfigurationElementCollection]$vdirs = $rootApp.GetCollection()
        $vdir = $vdirs.CreateElement('virtualDirectory')
        Write-IisVerbose $SiteName -VirtualPath $VirtualPath 'VirtualPath' '' $VirtualPath
        $vdir['path'] = $VirtualPath
        [void]$vdirs.Add( $vdir )
        $modified = $true
    }

    if( $vdir['physicalPath'] -ne $PhysicalPath )
    {
        Write-IisVerbose $SiteName -VirtualPath $VirtualPath 'PhysicalPath' $vdir['physicalPath'] $PhysicalPath
        $vdir['physicalPath'] = $PhysicalPath
        $modified = $true
    }

    if( $modified )
    {
        $site.CommitChanges()
    }
}

,benign

