function Assert-Tags($tags1, $tags2)
{
    if($tags1.count -ne $tags2.count)
    {
        throw "Tag size not equal. Tag1: $tags1.count Tag2: $tags2.count"
    }

    foreach($key in $tags1.Keys)
    {
        if($tags1[$key] -ne $tags2[$key])
        {
            throw "Tag content not equal. Key:$key Tags1:" +  $tags1[$key] + "Tags2:" + $tags2[$key]
        }
    }
}


function Assert-CompressionTypes($types1, $types2)
{
    if($types1.Count -ne $types1.Count)
    {
        throw "Array size not equal. Types1: $types1.count Types2: $types2.count"
    }

    foreach($value1 in $types1)
    {
        $found = $false
        foreach($value2 in $types2)
        {
            if($value1.CompareTo($value2) -eq 0)
            {
                $found = $true
                break
            }
        }
        if(-Not($found))
        {
            throw "Compression content not equal. " + $value1 + " cannot be found in second array"
        }
    }
},benign

function Export-SPLists{



	param(	
		[Parameter(Mandatory=$true)]
		[String[]]
		$Urls,

		[Parameter(Mandatory=$false)]
		[String]
		$Path = "C:\temp"
	)




    if ((Get-PSSnapin "Microsoft.SharePoint.PowerShell" -ErrorAction SilentlyContinue) -eq $null) 
    {
        Add-PSSnapin "Microsoft.SharePoint.PowerShell"
    }







	foreach($UrlItem in $Urls){


        $Url = Get-CleanSPUrl -Url $UrlItem        

        $SPWeb = Get-SPWeb -Identity ($Url.WebUrl.Scheme + "://" + $Url.WebUrl.Host + $Url.WebUrl.LocalPath)


        if(!(Test-Path -path $Path)){New-Item $Path -Type Directory}

        $FileName = ($Url.ListUrl.LocalPath -replace ".*/","")

        Write-Progress -Activity "Export SharePoint list" -status $FileName -percentComplete ([int]([array]::IndexOf($Urls, $UrlItem)/$Urls.Count*100))


        $FilePath = Join-Path -Path $Path -ChildPath ( $FileName + "

		Export-SPWeb -Identity $SPWeb.Url -ItemUrl $Url.ListUrl.LocalPath -Path $FilePath  -IncludeVersions All -IncludeUserSecurity -Force -NoLogFile -CompressionSize 1000

        $FilePath

	}
}
,benign

