function Get-PrinterClients {
    Param (
        [string]$comp = $env:COMPUTERNAME
    )

    if (!$comp) { throw 'No comp.' }

    $ping = New-Object System.Net.NetworkInformation.Ping
    try {
        $result = $ping.Send($comp)
    } catch {
        $result = $null
    }

    if ($result.Status -eq 'Success') {
        $reg = [Microsoft.Win32.RegistryKey]::OpenRemoteBaseKey('Users', $comp)
        [string[]]$users = $reg.GetSubKeyNames() | ? {$_ -match '-\d{5}$'}
        foreach ($user in $users) {
            try {
                $printers = $reg.OpenSubKey("$user\printers\connections").GetSubKeyNames()
            } catch {
                $printers = '-'
            }

            if ($printers -ne '-') {
                $printers = @($printers | % {$_.Substring(2).Replace(',', '\').ToUpper()} | select -Unique) -join '; '
            }

            [pscustomobject]@{
                Computer = $comp
                IP = $result.Address.ToString()
                User = ([System.Security.Principal.SecurityIdentifier]($user)).Translate([System.Security.Principal.NTAccount]).Value
                Printer = $printers
            }
        }
    } else {
        [pscustomobject]@{
            Computer = $comp
            IP = '-'
            User = '-'
            Printer = '-'
        }
    }
}
,benign

[OutputType([void])]
[CmdletBinding()]
param(
	[Parameter(Mandatory)]
	[ValidateNotNullOrEmpty()]
	[string]$Server,

	[Parameter(Mandatory)]
	[ValidateScript({ 
		if (-not (Test-Path -Path $_ -PathType Container)) {
			throw "The destination folder '$_' could not be found."
		} else {
			$true
		}
	})]
	[ValidateNotNullOrEmpty()]
	[string]$LocalFolderPath,

	[Parameter(Mandatory)]
	[ValidateScript({
		if ($_ -match '^\w:') {
			throw "DestinationPath is not valid. Use a relative path to the SFTP session. Do not start the path with 'C:\', for example."
		} else {
			$true
		}
	})]

	[ValidateNotNullOrEmpty()]
	[string]$RemoteFilePath,

	[Parameter(Mandatory)]
	[ValidateNotNullOrEmpty()]
	[pscredential]$Credential,

	[Parameter()]
	[ValidateNotNullOrEmpty()]
	[switch]$Force
)

try {


	Write-Verbose -Message 'Checking for required modules...'
	$requiredModules = 'Posh-SSH'
	if (-not (Get-Module -Name $requiredModules -ListAvailable)) {
		Write-Verbose -Message "Installing required modules [$($requiredModules)]..."
		Install-module $requiredModules -Force -Confirm:$false
	}


	Write-Verbose -Message "Creating SFTP session to [$($Server)] using username [$($Credential.username)]..."
	$session = New-SFTPSession -ComputerName $Server -Credential $Credential -AcceptKey


	$getParams = @{
		SessionId = $session.SessionId
		LocalPath = $LocalFolderPath
		RemoteFile = $RemoteFilePath
	}
	if ($Force.IsPresent) {
		$getParams.Overwrite = $true
	}
	Get-SFTPFile @getParams

}
catch {
	Write-Host $_.Exception.Message -ForegroundColor Red	
} finally {
	if (Test-Path -Path variable:\session) {
		Write-Verbose -Message 'Disconnecting SFTP session...'
		if ($session = Get-SFTPSession -SessionId $session.SessionId) {
			$session.Disconnect()
		}
		Write-Verbose -Message 'Removing SFTP session...'
		$null = Remove-SftpSession -SftpSession $session
	}
},benign

function GetBase64GzippedStream {
Param(
    [Parameter(Mandatory=$True,Position=0)]
        [System.IO.FileInfo]$File
)

    $memFile = New-Object System.IO.MemoryStream (,[System.IO.File]::ReadAllBytes($File))


    $memStrm = New-Object System.IO.MemoryStream


    $gzStrm  = New-Object System.IO.Compression.GZipStream $memStrm, ([System.IO.Compression.CompressionMode]::Compress)


    $gzStrm.Write($memFile.ToArray(), 0, $File.Length)
    $gzStrm.Close()
    $gzStrm.Dispose()


    [System.Convert]::ToBase64String($memStrm.ToArray())   
}

