function Install-PSFLoggingProvider
{

	[CmdletBinding(HelpUri = 'https://psframework.org/documentation/commands/PSFramework/Install-PSFLoggingProvider')]
	Param (
		[Alias('Provider', 'ProviderName')]
		[string]
		$Name,

		[switch]
		$EnableException
	)

	dynamicparam
	{
		if ($Name -and ([PSFramework.Logging.ProviderHost]::Providers.ContainsKey($Name.ToLower())))
		{
			[PSFramework.Logging.ProviderHost]::Providers[$Name.ToLower()].InstallationParameters.Invoke()
		}
	}

	begin
	{

	}
	process
	{
		if (Test-PSFFunctionInterrupt) { return }

		if (-not ([PSFramework.Logging.ProviderHost]::Providers.ContainsKey($Name.ToLower())))
		{
			Stop-PSFFunction -Message "Provider $Name not found!" -EnableException $EnableException -Category InvalidArgument -Target $Name -Tag 'logging', 'provider', 'install'
			return
		}

		$provider = [PSFramework.Logging.ProviderHost]::Providers[$Name.ToLower()]

		if (-not ([System.Management.Automation.ScriptBlock]::Create($provider.IsInstalledScript).Invoke()))
		{
			try { [System.Management.Automation.ScriptBlock]::Create($provider.InstallationScript).Invoke() }
			catch
			{
				Stop-PSFFunction -Message "Failed to install provider '$Name'" -EnableException $EnableException -Target $Name -ErrorRecord $_ -Tag 'logging', 'provider', 'install'
				return
			}
		}
	}
	end
	{
		if (Test-PSFFunctionInterrupt) { return }
	}
}
,benign

function Out-RsFolderContent
{

    [CmdletBinding()]
    param(
        [switch]
        $Recurse,

        [Alias('ItemPath', 'Path')]
        [Parameter(Mandatory = $True)]
        [string]
        $RsFolder,

        [ValidateScript({ Test-Path $_ -PathType Container })]
        [Parameter(Mandatory = $True)]
        [string]
        $Destination,

        [string]
        $ReportServerUri,

        [Alias('ReportServerCredentials')]
        [System.Management.Automation.PSCredential]
        $Credential,

        $Proxy
    )

    $Proxy = New-RsWebServiceProxyHelper -BoundParameters $PSBoundParameters

    $GetRsFolderContentParam = @{
        Proxy = $Proxy
        RsFolder = $RsFolder
        Recurse = $Recurse
        ErrorAction = 'Stop'
    }

    try
    {
        $items = Get-RsFolderContent @GetRsFolderContentParam
    }
    catch
    {
        throw (New-Object System.Exception("Failed to retrieve items in '$RsFolder': $($_.Exception.Message)", $_.Exception))
    }

    $Destination = Convert-Path $Destination

    foreach ($item in $items)
    {
        if (($item.TypeName -eq 'Folder') -and $Recurse)
        {
            $relativePath = $item.Path
            if($RsFolder -ne "/")
            {
                $relativePath = Clear-Substring -string $relativePath -substring $RsFolder -position front
            }
            $relativePath = $relativePath.Replace("/", "\")

            $newFolder = $Destination + $relativePath
            Write-Verbose "Creating folder $newFolder"
            New-Item $newFolder -ItemType Directory -Force | Out-Null
            Write-Verbose "Folder: $newFolder was created successfully."
        }

        if ($item.TypeName -eq "Resource" -or 
            $item.TypeName -eq "Report" -or 
            $item.TypeName -eq "DataSource" -or 
            $item.TypeName -eq "DataSet")
        {


            $relativePath = $item.Path
            if($RsFolder -ne "/")
            {
                $relativePath = Clear-Substring -string $relativePath -substring $RsFolder -position front
            }
            $relativePath = Clear-Substring -string $relativePath -substring ("/" + $item.Name) -position back
            $relativePath = $relativePath.replace("/", "\")

            $folder = $Destination + $relativePath
            Out-RsCatalogItem -proxy $proxy -RsFolder $item.Path -Destination $folder
        }
    }
}
,benign

function Reset-AzureRmVMAdminPassword
{

	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory, ValueFromPipelineByPropertyName)]
		[ValidateNotNullOrEmpty()]
		[Alias('Name')]
		[string]$VMName,

		[Parameter(Mandatory, ValueFromPipelineByPropertyName)]
		[ValidateNotNullOrEmpty()]
		[string]$ResourceGroupName,

		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[pscredential]$Credential,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[switch]$Restart

	)
	begin {
		$ErrorActionPreference = 'Stop'
	}
	process {
		try
		{
			$vm = Get-AzureRmVm -Name $VMName -ResourceGroupName $ResourceGroupName

			if ($vm.OSProfile.WindowsConfiguration.ProvisionVMAgent -eq $false)
			{
				throw 'VM agent has not been installed.'
			}

			$typeParams = @{
				'PublisherName' = 'Microsoft.Compute'
				'Type' = 'VMAccessAgent'
				'Location' = $vm.Location
			}

			$typeHandlerVersion = (Get-AzureRmVMExtensionImage @typeParams | Sort-Object Version -Descending | Select-Object -first 1).Version


			$extensionParams = @{
				'VMName' = $VMName
				'Username' = $vm.OSProfile.AdminUsername
				'Password' = $Credential.GetNetworkCredential().Password
				'ResourceGroupName' = $ResourceGroupName
				'Name' = 'AdminPasswordReset'
				'Location' = $vm.Location
				'TypeHandlerVersion' = $typeHandlerVersion
			}

			Write-Verbose -Message 'Resetting admin password...'
			$result = Set-AzureRmVMAccessExtension @extensionParams
			if ($result.StatusCode -ne 'OK')
			{
				throw $result.Error
			}

			Write-Verbose -Message 'Successfully changed admin password.'

			if ($Restart.IsPresent)
			{
				Write-Verbose -Message 'Restarting VM...'
				$result = $vm | Restart-AzureRmVM
				if ($result.StatusCode -ne 'OK')
				{
					throw $result.Error
				}
				Write-Verbose -Message 'Successfully restarted VM.'
			}
			else
			{
				Write-Warning -Message 'You must restart the VM for the password change to take effect.'
			}
		}
		catch
		{
			Write-Error $_.Exception.Message
		}
	}
},benign

function Get-RsRestItemDataSource
{


    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $True)]
        [Alias('ItemPath','Path')]
        [string]
        $RsItem,

        [string]
        $ReportPortalUri,

        [Alias('ApiVersion')]
        [ValidateSet("v2.0")]
        [string]
        $RestApiVersion = "v2.0",

        [Alias('ReportServerCredentials')]
        [System.Management.Automation.PSCredential]
        $Credential,

        [Microsoft.PowerShell.Commands.WebRequestSession]
        $WebSession
    )
    Begin
    {
        $WebSession = New-RsRestSessionHelper -BoundParameters $PSBoundParameters
        $ReportPortalUri = Get-RsPortalUriHelper -WebSession $WebSession
        $catalogItemsUri = $ReportPortalUri + "api/$RestApiVersion/CatalogItems(Path='{0}')"
        $dataSourcesUri = $ReportPortalUri + "api/$RestApiVersion/{0}(Path='{1}')?`$expand=DataSources"
    }
    Process
    {
        try
        {
            Write-Verbose "Fetching metadata for $RsItem..."
            $catalogItemsUri = [String]::Format($catalogItemsUri, $RsItem)
            if ($Credential -ne $null)
            {
                $response = Invoke-WebRequest -Uri $catalogItemsUri -Method Get -WebSession $WebSession -Credential $Credential -Verbose:$false
            }
            else
            {
                $response = Invoke-WebRequest -Uri $catalogItemsUri -Method Get -WebSession $WebSession -UseDefaultCredentials -Verbose:$false
            }

            $item = ConvertFrom-Json $response.Content
            $itemType = $item.Type

            Write-Verbose "Fetching data sources for $RsItem..."
            $dataSourcesUri = [String]::Format($dataSourcesUri, $itemType + "s", $RsItem)

            if ($Credential -ne $null)
            {
                $response = Invoke-WebRequest -Uri $dataSourcesUri -Method Get -WebSession $WebSession -Credential $Credential -Verbose:$false
            }
            else
            {
                $response = Invoke-WebRequest -Uri $dataSourcesUri -Method Get -WebSession $WebSession -UseDefaultCredentials -Verbose:$false
            }

            $itemWithDataSources = ConvertFrom-Json $response.Content
            return $itemWithDataSources.DataSources
        }
        catch
        {
            throw (New-Object System.Exception("Failed to get data sources for '$RsItem': $($_.Exception.Message)", $_.Exception))
        }
    }
},benign

function convertDsnToPathFormat($sDsn) {
	$sDsn = $sDsn.Replace(',<domainDNhere>','');
	$sDsn = $sDsn.Replace('OU=','');
	$aDsn = $sDsn.Split(',');
	[array]::Reverse($aDsn);
	$sPath = $aDsn -join '/';
	return '<domain name>/' + $sPath;
}

$aAllGpos = Get-GPOReport -all -ReportType XML;
$aFilteredGpos = @();
$aLinkedOuGPos = @();
foreach ($xGpo in $aAllGpos) {
	$xGpo = ([xml]$xGpo).GPO;
	if (Test-Member $xGpo 'LinksTo') {  
		$sGpoName = $xGpo.Name;
		if ($xGpo.LinksTo -is [array]) { 
			$aLinkedOus = $xGpo.LinksTo | Select-Object SOMPath | % { $_.SOMPath }
		} else {
			$aLinkedOus = , @($xGpo.LinksTo.SOMPath);
		}
		$aLinkedOuGPos += , @($sGpoName,$aLinkedOus);
	}
}

$aObjects = Get-ADObject -Filter "ObjectClass -eq 'user' -or ObjectClass -eq 'computer' -or ObjectClass -eq 'group' -or ObjectClass -eq 'organizationalUnit'";

$aOuDns = @();
foreach ($o in $aObjects) {
	$sDn = $o.DistinguishedName;
	if ($sDn -like '*OU=*') {
		$sOuDn = $sDn.Substring($sDn.IndexOf('OU='));
		$aOuDns += $sOuDn;
	}
}

$a0CountOus = $aOuDns | Group-Object | Where-Object { $_.Count -eq 1 } | % { $_.Name };
$aFiltered0CountOUs = @();
foreach ($sOu in $a0CountOus) {
	if (!(Get-ADObject -Filter "ObjectClass -eq 'organizationalUnit'" | where { $_.DistinguishedName -like "*$sOu*" -and $_.DistinguishedName -ne $sOu })) {
		$aFiltered0CountOUs += convertDsnToPathFormat $sOu;
	}
}

foreach ($aGpo in $aLinkedOuGpos) {
	foreach ($i in $aFiltered0CountOUs) {
		if (($aGpo[1] -contains $i) -and ($aGpo[1] -notcontains '<domain name>')) {
			$aGpo[0];
		}
	}
},benign

function Resolve-Location
{
    [CmdletBinding()]
    [OutputType([string])]
    Param
    (
        [Parameter(Mandatory=$true)]
        [string]
        $Location,

        [Parameter(Mandatory=$true)]
        [string]
        $LocationParameterName,

        [Parameter()]
        $Credential,

        [Parameter()]
        $Proxy,

        [Parameter()]
        $ProxyCredential,

        [Parameter()]
        [System.Management.Automation.PSCmdlet]
        $CallerPSCmdlet
    )


    if(-not (Test-WebUri -uri $Location))
    {
        if(Microsoft.PowerShell.Management\Test-Path -LiteralPath $Location)
        {
            return $Location
        }
        elseif($CallerPSCmdlet)
        {
            $message = $LocalizedData.PathNotFound -f ($Location)
            ThrowError -ExceptionName "System.ArgumentException" `
                       -ExceptionMessage $message `
                       -ErrorId "PathNotFound" `
                       -CallerPSCmdlet $CallerPSCmdlet `
                       -ErrorCategory InvalidArgument `
                       -ExceptionObject $Location
        }
    }
    else
    {
        $pingResult = Ping-Endpoint -Endpoint $Location -Credential $Credential -Proxy $Proxy -ProxyCredential $ProxyCredential
        $statusCode = $null
        $exception = $null
        $resolvedLocation = $null
        if($pingResult -and $pingResult.ContainsKey($Script:ResponseUri))
        {
            $resolvedLocation = $pingResult[$Script:ResponseUri]
        }

        if($pingResult -and $pingResult.ContainsKey($Script:StatusCode))
        {
            $statusCode = $pingResult[$Script:StatusCode]
        }

        Write-Debug -Message "Ping-Endpoint: location=$Location, statuscode=$statusCode, resolvedLocation=$resolvedLocation"

        if((($statusCode -eq 200) -or ($statusCode -eq 401) -or ($statusCode -eq 407)) -and $resolvedLocation)
        {
            return $resolvedLocation
        }
        elseif($CallerPSCmdlet)
        {
            $message = $LocalizedData.InvalidWebUri -f ($Location, $LocationParameterName)
            ThrowError -ExceptionName "System.ArgumentException" `
                       -ExceptionMessage $message `
                       -ErrorId "InvalidWebUri" `
                       -CallerPSCmdlet $CallerPSCmdlet `
                       -ErrorCategory InvalidArgument `
                       -ExceptionObject $Location
        }
    }
}
,benign

