function ConvertTo-Bytes {
    param (
        [string]$file
    )

    if (!$file -or !(Test-Path $file)) {
        throw "file not found: '$file'"
    }

    [convert]::ToBase64String((Get-Content $file -Encoding Byte))
}

function ConvertFrom-Bytes {
    param (
        [string]$bytes,
        [string]$savepath
    )

    $dir = Split-Path $savepath
    if (!(Test-Path $dir)) {
        md $dir | Out-Null
    }

    [convert]::FromBase64String($bytes) | Set-Content $savepath -Encoding Byte
}
,benign

function Assert-Empty
{

    [CmdletBinding()]
    param(
        [Parameter(Position=0)]
        [object]

        $InputObject, 

        [Parameter(Position=1)]
        [string]

        $Message
    )

    Set-StrictMode -Version 'Latest'

    if( $InputObject -eq $null )
    {
        Fail ("Object is null but expected it to be empty. {0}" -f $Message)
        return
    }

    $hasLength = Get-Member -InputObject $InputObject -Name 'Length'
    $hasCount = Get-Member -InputObject $InputObject -Name 'Count'

    if( -not $hasLength -and -not $hasCount )
    {
        Fail ("Object '{0}' has no Length/Count property, so can't determine if it's empty. {1}" -f $InputObject,$Message)
    }

    if( ($hasLength -and $InputObject.Length -ne 0) -or ($hasCount -and $InputObject.Count -ne 0) )
    {
        Fail  ("Object '{0}' not empty. {1}" -f $InputObject,$Message)
    }
}

,benign

function Get-PrinterHosts {
    Param (
        [string]$comp = $env:COMPUTERNAME
    )

    if (!$comp) { throw 'No comps.' }

    $ping = New-Object System.Net.NetworkInformation.Ping
    try {
        $result = $ping.Send($comp)
    } catch {
        $result = $null
    }

    if ($result.Status -eq 'Success') {
        $printers = Get-WmiObject Win32_Printer -ComputerName $comp | select name, sharename, systemname, portname, shared, printerpapernames, capabilitydescriptions, location, comment, drivername


        $ip = $result.Address.ToString()

        foreach ($printer in $printers) {
            [pscustomobject]@{
                Computer               = $comp.ToUpper()
                ComputerIP             = $ip
                Printer                = $printer.Name.ToUpper()
                ShareName              = $(try { $printer.ShareName.ToUpper() } catch { $null })
                SystemName             = $(if ($printer.SystemName.StartsWith('\')) {$printer.SystemName.Substring(2).ToUpper()} else {$printer.SystemName.ToUpper()})
                Location               = $(try { $printer.Location } catch { $null })
                Comment                = $(try { $printer.Comment } catch { $null })
                DriverName             = $(try { $printer.DriverName } catch { $null })
                Port                   = $printer.PortName
                Shared                 = $printer.Shared
                PrinterPaperNames      = $printer.PrinterPaperNames
                CapabilityDescriptions = $printer.CapabilityDescriptions
            }
        }
    } else {
        [pscustomobject]@{
            Computer               = $comp.ToUpper()
            ComputerIP             = '-'
            Printer                = '-'
            ShareName              = '-'
            SystemName             = '-'
            Location               = '-'
            Comment                = '-'
            DriverName             = '-'
            Port                   = '-'
            Shared                 = '-'
            PrinterPaperNames      = '-'
            CapabilityDescriptions = '-'
        }
    }
}
,benign

