[System.Reflection.Assembly]::LoadWithPartialName('Microsoft.SqlServer.SqlWmiManagement')| Out-Null

function Set-SQLStartupParameters{
    [cmdletbinding(SupportsShouldProcess=$true)]
    param([string[]] $Instance
        ,[string[]] $StartupParameters
    )
    [bool]$SystemPaths = $false


    foreach($i in $Instance){

        $HostName = ($i.Split('\'))[0]
        $InstanceName = ($i.Split('\'))[1]


        $ServiceName = if($InstanceName){"MSSQL`$$InstanceName"}else{'MSSQLSERVER'}


        $smowmi = New-Object Microsoft.SqlServer.Management.Smo.Wmi.ManagedComputer $HostName
        $wmisvc = $smowmi.Services | Where-Object {$_.Name -eq $ServiceName}

        Write-Verbose "Old Parameters for $i :"
        Write-Verbose $wmisvc.StartupParameters


        $oldparams = $wmisvc.StartupParameters -split ';'
        $newparams = @()
        foreach($param in $StartupParameters){
            if($param.Substring(0,2) -match '-d|-e|-l'){
                $SystemPaths = $true
                $newparams += $param
                $oldparams = $oldparams | Where-Object {$_.Substring(0,2) -ne $param.Substring(0,2)}
            }
            else{
                $newparams += $param
            }
        }

        $newparams += $oldparams | Where-Object {$_.Substring(0,2) -match '-d|-e|-l'}
        $paramstring = ($newparams | Sort-Object) -join ';'

        Write-Verbose "New Parameters for $i :"
        Write-Verbose $paramstring


        if($PSCmdlet.ShouldProcess($i,$paramstring)){
            $wmisvc.StartupParameters = $paramstring
            $wmisvc.Alter()

            Write-Warning "Startup Parameters for $i updated. You will need to restart the service for these changes to take effect."
            If($SystemPaths){Write-Warning "You have changed the system paths for $i. Please make sure the paths are valid before restarting the service"}
        }
    }
},benign

function Save-ExcelasCSV {
    param (
        [string[]]$files = $(Throw 'No files provided.'),
        [string]$OutFolder,
        [switch]$Overwrite
    )

    BEGIN {
        function Release-Ref ($ref) {
            ([System.Runtime.InteropServices.Marshal]::ReleaseComObject([System.__ComObject]$ref) -gt 0)
            [System.GC]::Collect()
            [System.GC]::WaitForPendingFinalizers()
        }

        $xl = New-Object -ComObject Excel.Application
        $xl.DisplayAlerts = $false
        $xl.Visible = $false
    }

    PROCESS {
        foreach ($file in $files) {
            $file = Get-Item $file | ? {$_.Extension -match '^\.xlsx?$'}
            if (!$file) {continue}
            $wb = $xl.Workbooks.Open($file.FullName)

            if ($OutFolder) {
                $CSVfilename = Join-Path $OutFolder ($file.BaseName + '.csv')
            } else {
                $CSVfilename = $file.DirectoryName + '\' + $file.BaseName + '.csv'
            }

            if (!$Overwrite -and (Test-Path $CSVfilename)) {
                $num = 1
                $folder = Split-Path $CSVfilename
                $base = (Split-Path $CSVfilename -Leaf).Substring(0, (Split-Path $CSVfilename -Leaf).LastIndexOf('.'))
                $ext = $CSVfilename.Substring($CSVfilename.LastIndexOf('.'))
                while (Test-Path $CSVfilename) {
                    $CSVfilename = Join-Path $folder $($base + "-$num" + $ext)
                    $num += 1
                }
                $wb.SaveAs($CSVfilename, 6) 
            } else {
                $wb.SaveAs($CSVfilename, 6) 
            }

            $wb.Close($True)
            $CSVfilename
        }
    }

    END {
        $xl.Quit()
        $null = $wb, $xl | % {try{ Release-Ref $_ }catch{}}
    }
}
,benign

[CmdletBinding()]
param(

    [Parameter(Mandatory=$true)]
    [string]$TestExecPath,
    [Parameter(Mandatory=$false)]
    [string]$ModuleFilter
)

$dirPath = (Join-Path $PSScriptRoot -ChildPath '..')
$artPath = (Join-Path $dirPath 'artifacts')
$srcPath = (Join-Path $dirPath -ChildPath 'src')
$libPath = (Join-Path $srcPath -ChildPath 'lib')
$testConfig = (Join-Path $libPath -ChildPath 'test.net472.config')
$rmItems = Get-ChildItem -Recurse -Path $srcPath -Include *.Test.dll `
  | Where {$_.FullName.Contains('bin\Debug\netstandard2.0')}

if ($ModuleFilter)
{
    $rmItems = $rmItems | Where {$_.FullName.Contains($ModuleFilter)}
}

$success = $true

$rmItems | %{`
  Write-Host ("Testing " + $_.FullName)
  $testDir = $_.Directory.FullName
  $testExec = Get-Item $TestExecPath
  $testExecDir = $testExec.Directory.FullName
  $testExecFile = $testExec.Name
  $newExecPath = Join-Path $testDir -ChildPath $testExecFile
  $logFile = $_.Name -replace '.dll', '.log.xml'
  $logPath = (Join-Path $artPath $logFile)
  $copiedItems = (Get-ChildItem $testExecDir | Where-Object {$_.Name.StartsWith("xunit")})
  $copiedItems | Copy-Item -Destination $testDir
  try {

	  $process = Start-Process -FilePath $newExecPath `
		-Wait `
		-WorkingDirectory $testDir `
		-NoNewWindow `
		-ArgumentList $_.FullName, $testConfig, '-trait "AcceptanceType=CheckIn"', '-notrait "RunType=DesktopOnly"', '-notrait "RunType=CoreOnly"', "-xml $logPath"  -PassThru 
	  if ($process.ExitCode -ne 0) {
		$success = $false
	  }
  }
  finally {
    $copiedItems | %{Remove-Item -Force (Join-Path $testDir $_.Name)}
  }
}

if(-not $success) {
    Write-Warning 'Failure: One or more test case failed.'
    exit 1
}
