    [CmdletBinding()]
    param(

		[Parameter( Mandatory=$true)]
		[String]
		$Url,

		[Parameter( Mandatory=$false)]
		[String]
		$Path,

        [Switch]
        $Force
	)





    begin {

        $WebClient = New-Object System.Net.WebClient
        $Global:DownloadComplete = $false

        $eventDataComplete = Register-ObjectEvent $WebClient DownloadFileCompleted `
            -SourceIdentifier WebClient.DownloadFileComplete `
            -Action {$Global:DownloadComplete = $true}

        $eventDataProgress = Register-ObjectEvent $WebClient DownloadProgressChanged `
            -SourceIdentifier WebClient.DownloadProgressChanged `
            -Action { $Global:DPCEventArgs = $EventArgs }    
    } 

    process{

        $PathAndFilename = Get-PathAndFilename $Path

        if(-not $PathAndFilename.Filename){$PathAndFilename.Filename = (Split-Path ([uri]$Url).LocalPath -Leaf)}
        if(-not $PathAndFilename.Path){$PathAndFilename.Path = (Get-Location).Path}
        if(-not (Test-Path $PathAndFilename.Path)){New-Item -Path $PathAndFilename.Path -ItemType Directory}
        $Path = Join-Path $PathAndFilename.Path ($PathAndFilename.Filename)

        Write-Progress -Activity "Downloading file" -Status $Url

        $WebClient.DownloadFileAsync($Url, $Path)

        while (!($Global:DownloadComplete)) {                
            $ProgressPercentage = $Global:DPCEventArgs.ProgressPercentage
            if ($ProgressPercentage -ne $null) {
                Write-Progress -Activity "Downloading file" -Status $Url -PercentComplete $ProgressPercentage
            }
        }

        Write-Progress -Activity "Downloading file" -Status $Url -Complete

        $PathAndFilename
    }   

    end{

        Unregister-Event -SourceIdentifier WebClient.DownloadProgressChanged
        Unregister-Event -SourceIdentifier WebClient.DownloadFileComplete
        $WebClient.Dispose()
        $Global:DownloadComplete = $null
        $Global:DPCEventArgs = $null
        Remove-Variable WebClient
        Remove-Variable eventDataComplete
        Remove-Variable eventDataProgress
        [GC]::Collect()    
    }  
}  ,benign

function Get-User {
    param (
        [string]$comp = $env:COMPUTERNAME,
        [ValidateSet('computersystem', 'process', 'dir')]
        $method = 'computersystem'
    )

    switch ($method) {
        'dir' {
            Get-ChildItem \\$comp\c$\users -Directory -Exclude '*$*' | % {Get-ChildItem $_.FullName ntuser.dat* -Force -ea 0} | sort LastWriteTime -Descending | select @{n='Computer';e={$comp}}, @{n='User';e={Split-Path (Split-Path $_.FullName) -Leaf}}, LastWriteTime | ? user -notmatch '\.net'| group computer, user | % {$_.group | select -f 1}
        }

        'computersystem' {
            try {
                (Get-WmiObject win32_computerSystem -ComputerName $comp).username
            } catch {
                try {
                    [Microsoft.Win32.RegistryKey]::OpenRemoteBaseKey('LocalMachine', $comp).OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI').getvalue('LastLoggedOnUser')
                    Get-WmiObject Win32_NetworkLoginProfile -ComputerName $comp
                } catch {
                    'Error'
                }
            }
        }

        'process' {
            $owners = @{}
            Get-WmiObject win32_process -Filter 'name = "explorer.exe"' -ComputerName $comp | % {$owners[$_.handle] = $_.getowner().user}
            Get-Process explorer -ComputerName $comp | % {$owners[$_.id.tostring()]}
        }
    }
}
,benign

