Describe "Hierarchical paths" -Tags "CI" {
    BeforeAll {
        $data = "Hello World"
        Setup -File testFile.txt -Content $data
    }

    It "should work with Join-Path " {
        $testPath = Join-Path $TestDrive testFile.txt
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work with platform's slashes" {
        $testPath = "$TestDrive$([IO.Path]::DirectorySeparatorChar)testFile.txt"
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work with forward slashes" {
        $testPath = "$TestDrive/testFile.txt"
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work with backward slashes" {
        $testPath = "$TestDrive\testFile.txt"
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work with backward slashes for each separator" {
        $testPath = "$TestDrive\testFile.txt".Replace("/","\")
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work with forward slashes for each separator" {
        $testPath = "$TestDrive/testFile.txt".Replace("\","/")
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work even if there are too many forward slashes" {
        $testPath = "$TestDrive//////testFile.txt"
        Get-Content $testPath | Should -BeExactly $data
    }

    It "should work even if there are too many backward slashes" {
        $testPath = "$TestDrive\\\\\\\testFile.txt"
        Get-Content $testPath | Should -BeExactly $data
    }
}
,benign

function Remove-EnvironmentVariableValue{



    [CmdletBinding()]
    param(

		[Parameter(Mandatory=$true)]
		[String]
		$Name,

		[Parameter(Mandatory=$true)]
		[String]
		$Value, 

		[Parameter(Mandatory=$true)]
		[String]
		$Target,  

		[Switch]
		$Clear  
	)  





    [Environment]::GetEnvironmentVariable($Name,$Target) | %{

        if(($_.Contains($Value) -or (Invoke-Expression "`$env:$Name").contains($Value)) -and -not $Clear){

            Write-Host "Remove value: $Value from variable: $Name"            
            $Value = $_.Trim($Value)
            [Environment]::SetEnvironmentVariable($Name, $Value,$Target)
            Invoke-Expression "`$env:$Name = `"$Value`""

        }elseif($Clear){

            Write-Host "Set value from variable: $Name to `$null"
            [Environment]::SetEnvironmentVariable($Name,$null,$Target)    
            Invoke-Expression "`$env:$Name = `$null"        
        }
    }     
}       ,benign

function Get-Type {

    [cmdletbinding()]
    param(
        [string]$Module = '*',
        [string]$Assembly = '*',
        [string]$FullName = '*',
        [string]$Namespace = '*',
        [string]$BaseType = '*',
        [switch]$IsEnum
    )


        $WhereArray = @('$_.IsPublic')
        if($Module -ne "*"){$WhereArray += '$_.Module -like $Module'}
        if($Assembly -ne "*"){$WhereArray += '$_.Assembly -like $Assembly'}
        if($FullName -ne "*"){$WhereArray += '$_.FullName -like $FullName'}
        if($Namespace -ne "*"){$WhereArray += '$_.Namespace -like $Namespace'}
        if($BaseType -ne "*"){$WhereArray += '$_.BaseType -like $BaseType'}

        if($PSBoundParameters.ContainsKey("IsEnum")) { $WhereArray += '$_.IsENum -like $IsENum' }


        $WhereString = $WhereArray -Join " -and "
        $WhereBlock = [scriptblock]::Create( $WhereString )
        Write-Verbose "Where ScriptBlock: { $WhereString }"


        [AppDomain]::CurrentDomain.GetAssemblies() | ForEach-Object {
            Write-Verbose "Getting types from $($_.FullName)"
            Try
            {
                $_.GetExportedTypes()
            }
            Catch
            {
                Write-Verbose "$($_.FullName) error getting Exported Types: $_"
                $null
            }

        } | Where-Object -FilterScript $WhereBlock
}

,benign

Function Remove-ServiceNowAttachment {


    [System.Diagnostics.CodeAnalysis.SuppressMessage('PSAvoidUsingConvertToSecureStringWithPlainText','')]
    [System.Diagnostics.CodeAnalysis.SuppressMessage('PSAvoidGlobalVars','')]

    [CmdletBinding(DefaultParameterSetName,SupportsShouldProcess=$true)]
    Param(

        [Parameter(
            Mandatory=$true,
            ValueFromPipelineByPropertyName = $true
        )]
        [Alias('sys_id')]
        [string]$SysID,


        [Parameter(ParameterSetName='SpecifyConnectionFields', Mandatory=$true)]
        [ValidateNotNullOrEmpty()]
        [Alias('ServiceNowCredential')]
        [PSCredential]$Credential,


        [Parameter(ParameterSetName='SpecifyConnectionFields', Mandatory=$true)]
        [ValidateScript({Test-ServiceNowURL -Url $_})]
        [ValidateNotNullOrEmpty()]
        [Alias('Url')]
        [string]$ServiceNowURL,


        [Parameter(ParameterSetName='UseConnectionObject', Mandatory=$true)]
        [ValidateNotNullOrEmpty()]
        [Hashtable]$Connection
    )

	begin {}
	process	{



        Switch ($PSCmdlet.ParameterSetName) {
            'SpecifyConnectionFields' {
                $ApiUrl = 'https://' + $ServiceNowURL + '/api/now/v1/attachment'
                break
            }
            'UseConnectionObject' {
                $SecurePassword = ConvertTo-SecureString $Connection.Password -AsPlainText -Force
                $Credential = New-Object System.Management.Automation.PSCredential ($Connection.Username, $SecurePassword)
                $ApiUrl = 'https://' + $Connection.ServiceNowUri + '/api/now/v1/attachment'
                break
            }
            Default {
                If (Test-ServiceNowAuthIsSet) {
                    $Credential = $Global:ServiceNowCredentials
                    $ApiUrl = $Global:ServiceNowRESTURL + '/attachment'
                }
                Else {
                    Throw "Exception:  You must do one of the following to authenticate: `n 1. Call the Set-ServiceNowAuth cmdlet `n 2. Pass in an Azure Automation connection object `n 3. Pass in an endpoint and credential"
                }
            }
        }

        $Uri = $ApiUrl + '/' + $SysID
        Write-Verbose "URI:  $Uri"

        $invokeRestMethodSplat = @{
            Uri         = $Uri
            Credential  = $Credential
            Method      = 'Delete'
        }

        If ($PSCmdlet.ShouldProcess($Uri,$MyInvocation.MyCommand)) {
            (Invoke-RestMethod @invokeRestMethodSplat).Result
        }
    }
	end {}
}
,benign

function Submit-SPOCheckOut
{
	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory=$true, Position=1)]
		[string]$targetPath
	)

	$targetPath = Join-SPOParts -Separator '/' -Parts $clientContext.Web.ServerRelativeUrl, $targetPath

    $remotefile = $clientContext.Web.GetFileByServerRelativeUrl($targetPath)
    $clientContext.Load($remotefile)
    $clientContext.ExecuteQuery()

    if ($remotefile.CheckOutType -eq [Microsoft.SharePoint.Client.CheckOutType]::None)
    {
        $remotefile.CheckOut()
    }
    $clientContext.ExecuteQuery()
}
,benign

function Add-SPOFolder
{
	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory=$true, Position=1)]
		[string]$folderUrl
	)


    $folderNameArr = $folderurl.Split('/')
    $folderName = $folderNameArr[$folderNameArr.length-1]

    $folderUrl = Join-SPOParts -Separator '/' -Parts $clientContext.Web.ServerRelativeUrl, $folderUrl
	$parentFolderUrl = $folderUrl.Replace('/' + $folderName,'')




    $web = $clientContext.Web
    $folder = $web.GetFolderByServerRelativeUrl($folderUrl)
    $clientContext.Load($folder)
    $alreadyExists = $false


    try
    {
        $clientContext.ExecuteQuery();

        if ($folder.Path)
        {
            $alreadyExists = $true;
        }
    }
    catch { }

    if (!$alreadyExists)
    {

		Write-Host "Create folder $folderName at $parentFolderUrl" -foregroundcolor black -backgroundcolor yellow


        $newItemInfo = new-object Microsoft.SharePoint.Client.ListItemCreationInformation
        $newItemInfo.UnderlyingObjectType = [Microsoft.SharePoint.Client.FileSystemObjectType]::Folder
        $newItemInfo.LeafName = $folderName
        $newItemInfo.FolderUrl = $parentFolderUrl


        $listUrl = Join-SPOParts -Separator '/' -Parts $clientContext.Web.ServerRelativeUrl, $folderNameArr[1]




		$method = [Microsoft.SharePoint.Client.ClientContext].GetMethod("Load")
		$loadMethod = $method.MakeGenericMethod([Microsoft.SharePoint.Client.List])

		$parameter = [System.Linq.Expressions.Expression]::Parameter(([Microsoft.SharePoint.Client.List]), "list")
		$expression = [System.Linq.Expressions.Expression]::Lambda(
			[System.Linq.Expressions.Expression]::Convert(
				[System.Linq.Expressions.Expression]::PropertyOrField(
					[System.Linq.Expressions.Expression]::PropertyOrField($parameter, "RootFolder"),
					"ServerRelativeUrl"
				),
				[System.Object]
			),
			$($parameter)
		)
		$expressionArray = [System.Array]::CreateInstance($expression.GetType(), 1)
		$expressionArray.SetValue($expression, 0)

		$lists = $web.Lists

		$clientContext.Load($lists)
		$clientContext.ExecuteQuery()

		$list = $null

		foreach	($listfinder in $lists) {
			$loadMethod.Invoke($clientContext, @($listfinder, $expressionArray))

			$clientContext.ExecuteQuery()

			if ($listfinder.RootFolder.ServerRelativeUrl -eq $listUrl)
			{
				$list = $listfinder
			}
		}

        $newListItem = $list.AddItem($newItemInfo)


        $newListItem.Update()


        $clientContext.Load($list);
        $clientContext.ExecuteQuery();
    }
}
