{

	[CmdletBinding(SupportsShouldProcess, ConfirmImpact = 'Low')]
	PARAM (
		[Parameter(ValueFromPipeline, ValueFromPipelineByPropertyName)]
		[ValidateScript({ Test-Path -Path $_ })]
		[Alias('FullName')]
		[System.String]$Path
	)
	PROCESS
	{
		FOREACH ($File in $Path)
		{
			Write-Verbose -Message '[PROCESS] $File'

			TRY
			{

				$ScriptContent = (Get-Content $File -Delimiter $([char]0))


				$AbstractSyntaxTree = [System.Management.Automation.Language.Parser]::
				ParseInput($ScriptContent, [ref]$null, [ref]$null)


				$Aliases = $AbstractSyntaxTree.FindAll({ $args[0] -is [System.Management.Automation.Language.CommandAst] }, $true) |
				ForEach-Object -Process {
					$Command = $_.CommandElements[0]
					if ($Alias = Get-Alias | Where-Object { $_.Name -eq $Command })
					{


						[PSCustomObject]@{
							File = $File
							Alias = $Alias.Name
							Definition = $Alias.Definition
							StartLineNumber = $Command.Extent.StartLineNumber
							EndLineNumber = $Command.Extent.EndLineNumber
							StartColumnNumber = $Command.Extent.StartColumnNumber
							EndColumnNumber = $Command.Extent.EndColumnNumber
							StartOffset = $Command.Extent.StartOffset
							EndOffset = $Command.Extent.EndOffset

						}
					}
				} | Sort-Object -Property EndOffset -Descending


				Foreach ($Alias in $Aliases)
				{

					if ($psCmdlet.ShouldProcess($file, "Expand Alias: $($Alias.alias) to $($Alias.definition) (startoffset: $($alias.StartOffset))"))
					{

						$ScriptContent = $ScriptContent.Remove($Alias.StartOffset, ($Alias.EndOffset - $Alias.StartOffset)).Insert($Alias.StartOffset, $Alias.Definition)

						Set-Content -Path $File -Value $ScriptContent -Confirm:$false
					}
				}

			}
			CATCH
			{
				Write-Error -Message $($Error[0].Exception.Message)
			}
		}
	}
},benign

function Remove-CGroupMember
{

    [CmdletBinding(SupportsShouldProcess=$true)]
    param(
        [Parameter(Mandatory=$true)]
        [string]

        $Name,

        [Parameter(Mandatory=$true)]
        [string[]]

		[Alias('Members')]
        $Member
    )

    Set-StrictMode -Version 'Latest'
    Use-CallerPreference -Cmdlet $PSCmdlet -Session $ExecutionContext.SessionState

    [DirectoryServices.AccountManagement.GroupPrincipal]$group = Get-CGroup -Name $Name
    if( -not $group )
    {
        return
    }

    try
    {
        foreach( $_member in $Member )
        {
            $identity = Resolve-CIdentity -Name $_member
            if( -not $identity )
            {
                continue
            }

            if( -not (Test-CGroupMember -GroupName $group.Name -Member $_member) )
            {
                continue
            }

            Write-Verbose -Message ('[{0}] Members      {1} ->' -f $Name,$identity.FullName)
            if( -not $PSCmdlet.ShouldProcess(('removing "{0}" from local group "{1}"' -f $identity.FullName, $group.Name), $null, $null) )
            {
                continue
            }

            try
            {
                $identity.RemoveFromLocalGroup( $group.Name )
            }
            catch
            {
                Write-Error ('Failed to remove "{0}" from local group "{1}": {2}.' -f $identity,$group.Name,$_)
            }
        }
    }
    finally
    {
        $group.Dispose()
    }
}

,benign

function Get-ARPCache
{
    [CmdletBinding()]
    param(

    )

    Begin{

    }

    Process{

        $RegexIPv4Address = "(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)"
        $RegexMACAddress = "([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})|([0-9A-Fa-f]{2}){6}"


        $Arp_Result = arp -a

        foreach($line in $Arp_Result)
        {

            if($line -like "*---*")
            {            
                Write-Verbose -Message "Interface $line"

                $InterfaceIPv4 = [regex]::Matches($line, $RegexIPv4Address).Value

                Write-Verbose -Message "$InterfaceIPv4"            
            }
            elseif($line -match $RegexMACAddress)
            {            
                foreach($split in $line.Split(" "))
                {
                    if($split -match $RegexIPv4Address)
                    {
                        $IPv4Address = $split
                    }
                    elseif ($split -match $RegexMACAddress) 
                    {
                        $MACAddress = $split.ToUpper()    
                    }
                    elseif(-not([String]::IsNullOrEmpty($split)))
                    {
                        $Type = $split
                    }
                }

                [pscustomobject] @{
                    Interface = $InterfaceIPv4
                    IPv4Address = $IPv4Address
                    MACAddress = $MACAddress
                    Type = $Type
                }
            }
        }
    }

    End{

    }
},benign

function Get-SourceName {
    [CmdletBinding()]
    [OutputType("string")]
    Param
    (
        [Parameter(Mandatory = $true)]
        [ValidateNotNullOrEmpty()]
        [string]
        $Location
    )

    Set-ModuleSourcesVariable

    foreach ($psModuleSource in $script:PSGetModuleSources.Values) {
        if (($psModuleSource.Name -eq $Location) -or
            (Test-EquivalentLocation -LocationA $psModuleSource.SourceLocation -LocationB $Location) -or
            ((Get-Member -InputObject $psModuleSource -Name $script:ScriptSourceLocation) -and
                (Test-EquivalentLocation -LocationA $psModuleSource.ScriptSourceLocation -LocationB $Location))) {
            return $psModuleSource.Name
        }
    }
}
,benign

$scriptBlock = {
	$script:___ScriptName = 'psframework.taskengine'

	try
	{

		while ($true)
		{

			if ([PSFramework.Runspace.RunspaceHost]::Runspaces[$___ScriptName.ToLower()].State -notlike "Running")
			{
				break
			}

			$task = $null
			$tasksDone = @()
			while ($task = [PSFramework.TaskEngine.TaskHost]::GetNextTask($tasksDone))
			{
				$task.State = 'Running'
				try
				{
					[PSFramework.Utility.UtilityHost]::ImportScriptBlock($task.ScriptBlock)
					$task.ScriptBlock.Invoke()
					$task.State = 'Pending'
				}
				catch
				{
					$task.State = 'Error'
					$task.LastError = $_
					Write-PSFMessage -EnableException $false -Level Warning -Message "[Maintenance] Task '$($task.Name)' failed to execute" -ErrorRecord $_ -FunctionName "task:TaskEngine" -Target $task -ModuleName PSFramework
				}
				$task.LastExecution = Get-Date
				if (-not $task.Pending -and ($task.Status -eq "Pending")) { $task.Status = 'Completed' }
				$tasksDone += $task.Name
			}


			if (-not ([PSFramework.TaskEngine.TaskHost]::HasPendingTasks)) { break }

			Start-Sleep -Seconds 5
		}

	}
	catch {  }
	finally
	{
		[PSFramework.Runspace.RunspaceHost]::Runspaces[$___ScriptName.ToLower()].SignalStopped()
	}
}

Register-PSFRunspace -ScriptBlock $scriptBlock -Name 'psframework.taskengine' -NoMessage,benign

