	$type = "sites"
	$location = Get-AzureRmResourceProvider -ProviderNamespace $namespace | where {$_.ResourceTypes[0].ResourceTypeName -eq $type}

	if ($location -eq $null) 
	{  
		return "West US"  
	} else 
	{  
		return $location.Locations[0]  
	}
}


