$namedInstance = new-object('Microsoft.SqlServer.Management.Smo.server') 'XSQLUTIL18'

$jobs = $namedInstance.jobserver.jobs 


foreach ($job in $jobs) 
{
	[int]$outcome = 0
	[string]$output = ""


	if ($job.LastRunOutcome -ne "Succeeded") 
	{
		$outcome++;
		$output = $output + " Job failed (" + $job.name + ")" + " Result: " + $job.LastRunOutcome;
	}
	elseif ($job.LastRunOutcome -eq "Succeeded")
	{
		$outcome++;
		$output = $output + " Job succeeded " + $job.Name + ")" + " Result: " + $job.LastRunOutcome;
	}


	foreach ($jobStep in $job.jobsteps) 
	{
		if ($jobStep.LastRunOutcome -ne "Succeeded")
		{
			$outcome++;
			$output = $output + " Step failed (" + $jobStep.name + ")" + " Result: " + $jobStep.LastRunOutcome + " -- ";
		}
		elseif ($jobstep.LastRunOutcome -eq "Succeeded")
		{
			$outcome++;
			$output = $output + " Step succeeded (" + $jobStep.Name + ")" + "Result: " + $jobStep.LastRunOutcome + " -- ";
		}
	}

	if ($outcome -gt 0)    
	{
		$obj = New-Object Object;
		$obj | Add-Member Noteproperty name -value $job.name;
		$obj | Add-Member Noteproperty lastrundate -value $job.lastrundate;
		$obj | Add-Member Noteproperty lastrunoutcome -value $output;
		$obj | Add-Member Noteproperty lastrunduration -value $jobStep.LastRunDuration;
		$obj
	}
},benign

function Resolve-PathHelper
{
    param
    (
        [Parameter()]
        [ValidateNotNullOrEmpty()]
        [string[]]
        $path,

        [Parameter()]
        [switch]
        $isLiteralPath,

        [Parameter()]
        [ValidateNotNullOrEmpty()]
        [System.Management.Automation.PSCmdlet]
        $callerPSCmdlet
    )

    $resolvedPaths =@()

    foreach($currentPath in $path)
    {
        try
        {
            if($isLiteralPath)
            {
                $currentResolvedPaths = Microsoft.PowerShell.Management\Resolve-Path -LiteralPath $currentPath -ErrorAction Stop
            }
            else
            {
                $currentResolvedPaths = Microsoft.PowerShell.Management\Resolve-Path -Path $currentPath -ErrorAction Stop
            }
        }
        catch
        {
            $errorMessage = ($LocalizedData.PathNotFound -f $currentPath)
            ThrowError  -ExceptionName "System.InvalidOperationException" `
                        -ExceptionMessage $errorMessage `
                        -ErrorId "PathNotFound" `
                        -CallerPSCmdlet $callerPSCmdlet `
                        -ErrorCategory InvalidOperation
        }

        foreach($currentResolvedPath in $currentResolvedPaths)
        {
            $resolvedPaths += $currentResolvedPath.ProviderPath
        }
    }

    $resolvedPaths
}
,benign

function Get-InstalledSoftware
	{
	[CmdletBinding()]
	param(
		[Parameter(
			Position=0,
			HelpMessage='Search for product name (You can use wildcards like "*ProductName*')]
		[String]$Search,

		[Parameter(
			Position=1,
			HelpMessage='ComputerName or IPv4-Address of the remote computer')]
		[String]$ComputerName = $env:COMPUTERNAME,

		[Parameter(
			Position=2,
			HelpMessage='Credentials to authenticate agains a remote computer')]
		[System.Management.Automation.PSCredential]
		[System.Management.Automation.CredentialAttribute()]
		$Credential
	)

	Begin{
		$LocalAddress = @("127.0.0.1","localhost",".","$($env:COMPUTERNAME)")

		[System.Management.Automation.ScriptBlock]$ScriptBlock = {

			return Get-ChildItem -Path  "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall", "HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall" | Get-ItemProperty | Select-Object -Property DisplayName, Publisher, UninstallString, InstallLocation, InstallDate
		}
	}

	Process{
		if($LocalAddress -contains $ComputerName)
		{			
			$Strings = Invoke-Command -ScriptBlock $ScriptBlock -ArgumentList $Search            
		}
		else
		{
			if(Test-Connection -ComputerName $ComputerName -Count 2 -Quiet)
			{
				try {
					if($PSBoundParameters.ContainsKey('Credential'))
					{
						$Strings = Invoke-Command -ScriptBlock $ScriptBlock -ComputerName $ComputerName -ArgumentList $Search -Credential $Credential -ErrorAction Stop
					}
					else
					{					    
						$Strings = Invoke-Command -ScriptBlock $ScriptBlock -ComputerName $ComputerName -ArgumentList $Search -ErrorAction Stop
					}
				}
				catch {
					throw 
				}
			}
			else 
			{				
				throw """$ComputerName"" is not reachable via ICMP!"
			}
		}

		foreach($String in $Strings)
		{

			if((-not([String]::IsNullOrEmpty($String.DisplayName))) -and (-not([String]::IsNullOrEmpty($String.UninstallString))))
			{

				if((-not($PSBoundParameters.ContainsKey('Search'))) -or (($PSBoundParameters.ContainsKey('Search') -and ($String.DisplayName -like $Search))))
				{                   
					[pscustomobject] @{
						DisplayName = $String.DisplayName
						Publisher = $String.Publisher
						UninstallString = $String.UninstallString
						InstallLocation = $String.InstallLocation
						InstallDate = $String.InstallDate
					}
				}   
			}
		}
	}

	End{

	}
}
,benign

function Get-CommandStatus {

    [PoshBot.BotCommand(
        Aliases = ('getcommandstatus', 'commandstatus')
    )]
    [cmdletbinding()]
    param(
        [parameter(Mandatory)]
        $Bot
    )

    $activeJobs = @($Bot.Executor._jobTracker.GetEnumerator() | Foreach-Object {
        $userId = $_.Value.ParsedCommand.From
        $userName = $Bot.RoleManager.ResolveUserIdToUserName($_.Value.ParsedCommand.From)
        $cmdDuration = [system.math]::Round(((Get-Date).ToUniversalTime() - $_.Value.Started.ToUniversalTime()).TotalSeconds, 0)
        [pscustomobject]@{
            Id = $_.Value.Id
            From = "$userName [$userId]"
            CommandString = $_.Value.ParsedCommand.CommandString
            Complete = $_.Value.Complete
            Started = $_.Value.Started.ToUniversalTime().ToString('u')
            RunningTime = "$cmdDuration seconds"
        }
    })

    if ($activeJobs.Count -eq 0) {
        New-PoshbotTextResponse -Text 'There are no active jobs'
    } else {
        $msg = ($activeJobs | Format-List -Property * | Out-String)
        New-PoshBotTextResponse -Text $msg -AsCode
    }
}
,benign

function Get-ManifestHashTable
{
    param
    (
        [Parameter(Mandatory=$true)]
        [ValidateNotNullOrEmpty()]
        [string]
        $Path,

        [Parameter()]
        [ValidateNotNullOrEmpty()]
        [System.Management.Automation.PSCmdlet]
        $CallerPSCmdlet
    )

    $Lines = $null

    try
    {
        $Lines = Get-Content -Path $Path -Force
    }
    catch
    {
        if($CallerPSCmdlet)
        {
            $CallerPSCmdlet.ThrowTerminatingError($_.Exception.ErrorRecord)
        }
    }

    if(-not $Lines)
    {
        return
    }

    $scriptBlock = [ScriptBlock]::Create( $Lines -join "`n" )

    $allowedVariables = [System.Collections.Generic.List[String]] @('PSEdition', 'PSScriptRoot')
    $allowedCommands = [System.Collections.Generic.List[String]] @()
    $allowEnvironmentVariables = $false

    try
    {
        $scriptBlock.CheckRestrictedLanguage($allowedCommands, $allowedVariables, $allowEnvironmentVariables)
    }
    catch
    {
        if($CallerPSCmdlet)
        {
            $CallerPSCmdlet.ThrowTerminatingError($_.Exception.ErrorRecord)
        }

        return
    }

    return $scriptBlock.InvokeReturnAsIs()
}
,benign

function Test-AzureProviderFeature
{
    $defaultProviderFeatures = Get-AzProviderFeature

    $allProviderFeatures = Get-AzProviderFeature -ListAvailable

    Assert-True { $allProviderFeatures.Length -gt $defaultProviderFeatures.Length }

    $batchFeatures = Get-AzProviderFeature -ProviderName "Microsoft.Batch"

    Assert-True { $batchFeatures.Length -eq 0 }

    $batchFeatures = Get-AzProviderFeature -ProviderName "Microsoft.Batch" -ListAvailable

    Assert-True { $batchFeatures.Length -gt 0 }

