function Get-SCSMServiceRequestComment
{


	PARAM
	(
		[Parameter(ParameterSetName = 'General',
				   Mandatory = $true)]
		$DateTime = $((Get-Date).AddHours(-24)),

		[Parameter(ParameterSetName = 'GUID')]
		$GUID
	)

	IF ($PSBoundParameters['GUID'])
	{
		$Tickets = Get-SCSMObject -id $GUID
	}
	ELSE
	{
		if ($DateTime -is [String]){ $DateTime = Get-Date $DateTime}
		$DateTime = $DateTime.ToString(“yyy-MM-dd HH:mm:ss”)
		$Tickets = Get-SCSMObject -Class (Get-SCSMClass System.WorkItem.servicerequest$) -Filter "CreatedDate -gt '$DateTime'" 
	}

	$Tickets |
	ForEach-Object {
		$CurrentTicket = $_
		$relatedObjects = Get-scsmrelatedobject -SMObject $CurrentTicket
		Foreach ($Comment in ($relatedObjects | Where-Object { $_.classname -eq 'System.WorkItem.TroubleTicket.UserCommentLog' -or $_.classname -eq 'System.WorkItem.TroubleTicket.AnalystCommentLog' -or $_.classname -eq 'System.WorkItem.TroubleTicket.AuditCommentLog'}))
		{

			[pscustomobject][ordered] @{
				TicketName = $CurrentTicket.Name
				TicketClassName = $CurrentTicket.Classname
				TicketDisplayName = $CurrentTicket.DisplayName
				TicketID = $CurrentTicket.ID
				TicketGUID = $CurrentTicket.get_id()
				TicketSupportGroup = $CurrentTicket.SupportGroup.displayname
				TicketAssignedTo = $CurrentTicket.AssignedTo
				TicketCreatedDate = $CurrentTicket.CreatedDate
				Comment = $Comment.Comment
				CommentEnteredBy = $Comment.EnteredBy
				CommentEnteredDate = $Comment.EnteredDate
				CommentClassName = $Comment.ClassName
			}
		}
	}
},benign

Function Add-SRComment
{

    [CmdletBinding()]
    PARAM (

        [Alias("SRObject")]
        [parameter(Mandatory = $true)]
        [System.WorkItem.ServiceRequest]$ServiceRequestObject,

        [parameter(Mandatory = $True)]
        [String]$Comment,

        [ValidateSet("User", "Analyst")]
        [parameter(Mandatory = $True)]
        [System.WorkItem.TroubleTicket]
        [String]$CommentType,

        [parameter(Mandatory = $True)]
        [String]$EnteredBy,

        [Switch]$IsPrivate
    )
    BEGIN
    {
        TRY
        {
            if (-not (Get-Module -Name Smlets))
            {
                Import-Module -Name Smlets -ErrorAction 'Stop'
            }
        }
        CATCH
        {
            $Error[0]
        }
    }
    PROCESS
    {
        TRY
        {

            If ($ServiceRequestObject.Id -ne $NULL)
            {
                Switch ($CommentType)
                {
                    "Analyst" {
                        $CommentClass = "System.WorkItem.TroubleTicket.AnalystCommentLog"
                        $CommentClassName = "AnalystCommentLog"
                    }
                    "User" {
                        $CommentClass = "System.WorkItem.TroubleTicket.UserCommentLog"
                        $CommentClassName = "EndUserCommentLog"
                    }
                }

                $NewGUID = ([guid]::NewGuid()).ToString()


                $Projection = @{
                    __CLASS = "System.WorkItem.ServiceRequest";
                    __SEED = $ServiceRequestObject;
                    EndUserCommentLog = @{
                        __CLASS = $CommentClass;
                        __OBJECT = @{
                            Id = $NewGUID;
                            DisplayName = $NewGUID;
                            Comment = $Comment;
                            EnteredBy = $EnteredBy;
                            EnteredDate = (Get-Date).ToUniversalTime();
                            IsPrivate = $IsPrivate.ToBool();
                        }
                    }
                }


                New-SCSMObjectProjection -Type "System.WorkItem.ServiceRequestProjection" -Projection $Projection
            }
            else
            {
                Throw "Invalid Service Request Object!"
            }
        }
        CATCH
        {
            $Error[0]
        } 
    } 
} ,benign

function Get-Role {

    [PoshBot.BotCommand(
        Aliases = ('gr', 'getrole'),
        Permissions = 'view-role'
    )]
    [cmdletbinding()]
    param(
        [parameter(Mandatory)]
        $Bot,

        [parameter(Position = 0)]
        [string]$Name
    )

    if ($PSBoundParameters.ContainsKey('Name')) {
        $r = $Bot.RoleManager.GetRole($Name)
        if (-not $r) {
            New-PoshBotCardResponse -Type Warning -Text "Role [$Name] not found :(" -Title 'Rut row' -ThumbnailUrl $thumb.rutrow
        } else {
            $msg = [string]::Empty
            $msg += "`nDescription: $($r.Description)"
            $msg += "`nPermissions:`n$($r.Permissions.Keys | Format-List | Out-String)"
            New-PoshBotCardResponse -Type Normal -Title "Details for role [$Name]" -Text $msg
        }
    } else {
        $roles = foreach ($key in ($Bot.RoleManager.Roles.Keys | Sort-Object)) {
            [pscustomobject][ordered]@{
                Name = $key
                Description = $Bot.RoleManager.Roles[$key].Description
                Permissions = $Bot.RoleManager.Roles[$key].Permissions.Keys
            }
        }
        New-PoshBotCardResponse -Type Normal -Text ($roles | Format-List | Out-String)
    }
}
