class LogMessage {
    [datetime]$DateTime = (Get-Date).ToUniversalTime()
    [string]$Class
    [string]$Method
    [LogSeverity]$Severity = [LogSeverity]::Normal
    [LogLevel]$LogLevel = [LogLevel]::Info
    [string]$Message
    [object]$Data

    LogMessage() {
    }

    LogMessage([string]$Message) {
        $this.Message = $Message
    }

    LogMessage([string]$Message, [object]$Data) {
        $this.Message = $Message
        $this.Data = $Data
    }

    LogMessage([LogSeverity]$Severity, [string]$Message) {
        $this.Severity = $Severity
        $this.Message = $Message
    }

    LogMessage([LogSeverity]$Severity, [string]$Message, [object]$Data) {
        $this.Severity = $Severity
        $this.Message = $Message
        $this.Data = $Data
    }


    hidden [string]Compact([string]$Json) {
        $indent = 0
        $compacted = ($Json -Split '\n' | ForEach-Object {
            if ($_ -match '[\}\]]') {

                $indent--
            }
            $line = (' ' * $indent * 2) + $_.TrimStart().Replace(':  ', ': ')
            if ($_ -match '[\{\[]') {

                $indent++
            }
            $line
        }) -Join "`n"
        return $compacted
    }

    [string]ToJson() {
        $json = [ordered]@{
            DataTime = $this.DateTime.ToString('u')
            Class = $this.Class
            Method = $this.Method
            Severity = $this.Severity.ToString()
            LogLevel = $this.LogLevel.ToString()
            Message = $this.Message
            Data = foreach ($item in $this.Data) {



                if ($item.GetType().BaseType.ToString() -eq 'System.Management.Automation.Job') {
                    continue
                }



                if ($item -is [System.Management.Automation.ErrorRecord]) {
                    [ExceptionFormatter]::Summarize($item)
                } else {
                    $item
                }
            }
        } | ConvertTo-Json -Depth 10 -Compress
        return $json
    }

    [string]ToString() {
        return $this.ToJson()
    }
}
,benign

function Compare-Folder
{
	[CmdletBinding()]
	param
	(
		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[ValidateScript({ Test-Path -Path $_ -PathType Container })]
		[string]$ReferenceFolder,

		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[ValidateScript({ Test-Path -Path $_ -PathType Container })]
		[string]$DifferenceFolder,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[ValidatePattern('^\\')]
		[string]$ExcludeFilePath

	)
	begin
	{
		$ErrorActionPreference = 'Stop'
		function Get-FileHashesInFolder
		{
			param (
				[string]$Folder
			)
			$files = Get-ChildItem -Path $Folder -Recurse -File
			foreach ($s in $files)
			{
				$selectObjects = @('Hash', @{ n = 'Path'; e = { $_.Path.SubString($Folder.Length) } })
				Get-FileHash $s.Fullname | Select $selectObjects -ExcludeProperty Path
			}
		}
	}
	process
	{
		try
		{
			$refHashes = Get-FileHashesInFolder -Folder $ReferenceFolder
			$destHashes = Get-FileHashesInFolder -Folder $DifferenceFolder
			if ($PSBoundParameters.ContainsKey('ExcludeFilePath'))
			{
				$refHashes = $refHashes.Where({ $_.Path -ne $ExcludeFilePath })
				$destHashes = $destHashes.Where({ $_.Path -ne $ExcludeFilePath })
			}

			$refHashes.Where({ $_.Path -notin $destHashes.Path }).foreach({
				[pscustomobject]@{
					'Path' = $_.Path
					'Reason' = 'NotInDifferenceFolder'
				}
			})
			$destHashes.Where({ $_.Path -notin $refHashes.Path }).foreach({
				[pscustomobject]@{
					'Path' = $_.Path
					'Reason' = 'NotInReferenceFolder'
				}
			})
			$refHashes.Where({ $_.Hash -notin $destHashes.Hash -and $_.Path -in $destHashes.Path }).foreach({
				[pscustomobject]@{
					'Path' = $_.Path
					'Reason' = 'HashDifferent'
				}
			})
		}
		catch
		{
			Write-Error $_.Exception.Message
		}
	}
},benign

