function Set-ScheduledCommand {

    [PoshBot.BotCommand(
        Aliases = ('setschedule', 'set-schedule'),
        Permissions = 'manage-schedules'
    )]
    [cmdletbinding()]
    param(
        [parameter(Mandatory)]
        $Bot,

        [parameter(Mandatory, Position = 0)]
        [string]$Id,

        [parameter(Mandatory, Position = 1)]
        [ValidateNotNull()]
        [int]$Value,

        [parameter(Mandatory, Position = 2)]
        [ValidateSet('days', 'hours', 'minutes', 'seconds')]
        [ValidateNotNullOrEmpty()]
        [string]$Interval,

        [ValidateScript({
            if ($_ -as [datetime]) {
                return $true
            } else {
                throw '''StartAfter'' must be a datetime.'
            }
        })]
        [string]$StartAfter
    )

    if ($scheduledMessage = $Bot.Scheduler.GetSchedule($Id)) {
        $scheduledMessage.TimeInterval = $Interval
        $scheduledMessage.TimeValue = $Value
        if ($PSBoundParameters.ContainsKey('StartAfter')) {
            $scheduledMessage.StartAfter = [datetime]$StartAfter
        }
        $scheduledMessage = $bot.Scheduler.SetSchedule($scheduledMessage)
        New-PoshBotCardResponse -Type Normal -Text "Schedule for command [$($scheduledMessage.Message.Text)] changed to every [$Value $($Interval.ToLower())]." -ThumbnailUrl $thumb.success
    } else {
        New-PoshBotCardResponse -Type Warning -Text "Scheduled command [$Id] not found." -ThumbnailUrl $thumb.warning
    }
}
,benign

function ConvertTo-ProviderAccessControlRights
{

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [ValidateSet('FileSystem','Registry','CryptoKey')]
        [string]

        $ProviderName,

        [Parameter(Mandatory=$true,ValueFromPipeline=$true)]
        [string[]]

        $InputObject
    )

    begin
    {
        Set-StrictMode -Version 'Latest'

        Use-CallerPreference -Cmdlet $PSCmdlet -Session $ExecutionContext.SessionState

        $rights = 0
        $rightTypeName = 'Security.AccessControl.{0}Rights' -f $ProviderName
        $foundInvalidRight = $false
    }

    process
    {
        $InputObject | ForEach-Object { 
            $right = ($_ -as $rightTypeName)
            if( -not $right )
            {
                $allowedValues = [Enum]::GetNames($rightTypeName)
                Write-Error ("System.Security.AccessControl.{0}Rights value '{1}' not found.  Must be one of: {2}." -f $providerName,$_,($allowedValues -join ' '))
                $foundInvalidRight = $true
                return
            }
            $rights = $rights -bor $right
        }
    }

    end
    {
        if( $foundInvalidRight )
        {
            return $null
        }
        else
        {
            $rights
        }
    }
}
,benign

function Invoke-Program {

	[CmdletBinding()]
	[OutputType([System.Management.Automation.PSObject])]
	param
	(
		[Parameter(Mandatory)]
		[ValidateNotNullOrEmpty()]
		[string]$FilePath,

		[Parameter(Mandatory)]
		[string]$ComputerName,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[string]$ArgumentList,

		[Parameter()]
		[bool]$ExpandStrings = $false,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[string]$WorkingDirectory,

		[Parameter()]
		[ValidateNotNullOrEmpty()]
		[uint32[]]$SuccessReturnCodes = @(0, 3010)
	)
	begin {
		$ErrorActionPreference = 'Stop'
	}
	process {
		try {
			Write-Verbose -Message "Acceptable success return codes are [$($SuccessReturnCodes -join ',')]"

			$scriptBlock = {
				$VerbosePreference = $using:VerbosePreference

				$processStartInfo = New-Object System.Diagnostics.ProcessStartInfo;
				$processStartInfo.FileName = $Using:FilePath;
				if ($Using:ArgumentList) {
					$processStartInfo.Arguments = $Using:ArgumentList;
					if ($Using:ExpandStrings) {
						$processStartInfo.Arguments = $ExecutionContext.InvokeCommandWithCred.ExpandString($Using:ArgumentList);
					}
				}
				if ($Using:WorkingDirectory) {
					$processStartInfo.WorkingDirectory = $Using:WorkingDirectory;
					if ($Using:ExpandStrings) {
						$processStartInfo.WorkingDirectory = $ExecutionContext.InvokeCommandWithCred.ExpandString($Using:WorkingDirectory);
					}
				}
				$processStartInfo.UseShellExecute = $false; 
				$ps = New-Object System.Diagnostics.Process;
				$ps.StartInfo = $processStartInfo;
				Write-Verbose -Message "Starting process path [$($processStartInfo.FileName)] - Args: [$($processStartInfo.Arguments)] - Working dir: [$($Using:WorkingDirectory)]"
				$null = $ps.Start();
				if (-not $ps) {
					throw "Error running program: $($ps.ExitCode)"
				} else {
					$ps.WaitForExit()
				}


				if ($ps.ExitCode -notin $Using:SuccessReturnCodes) {
					throw "Error running program: $($ps.ExitCode)"
				}
			}


			Write-Verbose -Message "Running command line [$FilePath $ArgumentList] on $ComputerName"

			Invoke-Command -ComputerName $ComputerName -ScriptBlock $scriptblock
		} catch {
			$PSCmdlet.ThrowTerminatingError($_)
		}
	}
},benign

